"""민수홍 포트폴리오 36쪽과 일대일 대응하는 발표·코드 학습 해설."""

SECTIONS = []


def add(n, why, elements, talk, details, qa, caution, refs, excerpt=None):
    SECTIONS.append(dict(n=n, why=why, elements=elements, talk=talk,
                         details=details, qa=qa, caution=caution,
                         refs=refs, excerpt=excerpt))


add(1,
    '표지는 기술 이름을 나열하기 전에 프로젝트가 해결하는 범위를 한 문장으로 기억시키는 역할이다. 성채 배경은 전장 분위기를 위한 문서용 이미지이며, 서버 실행 결과를 증명하는 자료는 본문의 실제 화면과 로그다.',
    [('C++ 멀티스레드 서버', '언어와 학습 주제를 먼저 보인다. 게임 전체의 상용 완성도보다 서버의 통신·계산·저장 흐름을 설명할 프로젝트임을 알린다.'),
     ('세 서버가 만나는 하나의 전장', 'Game 서버의 계정·유닛과 공용 World 전장을 연결하는 구조를 요약한다. 실제 네 개 프로세스의 관계는 3쪽에서 설명한다.'),
     ('IOCP · 전투 병렬 처리 · 메모리 풀', '뒤에서 코드와 측정으로 검증할 세 항목이다. 세 기능을 도입했다는 사실과 실제로 어떤 지표가 개선됐는지는 구분한다.')],
    '이 프로젝트는 세 Game 서버의 사용자가 공용 World 전장에 진입해 싸우는 C++ 서버입니다. 네트워크는 IOCP로 처리하고, 이동 등 독립 계산은 전투 쓰레드에 분담한 뒤 메인이 결과를 반영합니다. I/O 객체 풀과 DB·Redis·리플레이도 함께 구성했습니다. 지금부터 객체 소유권과 패킷 왕복을 먼저 보여드리고, 마지막에 비교 측정과 구현 한계를 설명하겠습니다.',
    [('처음 20초에 말할 범위', '개인 포트폴리오라는 점, C++ 더미 클라이언트로 검증했다는 점, Unreal 클라이언트는 후속 단계라는 점을 짧게 밝힌다. 표지의 세 기술을 모두 자세히 설명하려 하면 전체 흐름을 잃기 쉽다.'),
     ('배경과 근거의 구분', '배경을 실제 게임 화면이라고 설명하지 않는다. 시연 화면은 2·27쪽의 리플레이 뷰어, 정량 근거는 30~34쪽의 시험 기록을 연결해서 보여준다.')],
    [('이 프로젝트에서 가장 보여주고 싶은 것은?', '통신 쓰레드가 게임 상태를 직접 수정하지 않도록 경계를 두고, 계산과 상태 반영을 분리한 설계와 그 검증이다.'),
     ('세 기술이 들어갔으니 모두 빨라졌나요?', '도입 자체가 성능 향상을 보장하지 않는다. 뒤의 동일 부하 비교에서 응답 지연·Snapshot 비용·할당·CPU·메모리를 따로 확인했다.')],
    '표지 이미지, 구현된 기능, 실행 검증을 같은 종류의 근거처럼 섞지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/Main.cpp', 'int main('), ('Server.ini', '[Network]')])

add(2,
    '실제 화면을 크게 두고 오른쪽에 세 묶음의 설명을 배치해, 독자가 무엇을 구현했고 어떤 화면으로 확인했는지 동시에 파악하게 한다. 첫 기술 페이지 전에 게임 규칙의 맥락을 만드는 장이다.',
    [('왼쪽 실제 C++ 뷰어', '서버가 저장한 전장 기록을 복원한 화면이다. 서버가 매 순간 그림을 그려 보내는 구조가 아니라 좌표·HP 등의 상태를 저장하고 뷰어가 그린다.'),
     ('게임 서버 → 공용 World', '계정 로그인과 유닛 배정은 출발 Game 서버에서, 전장 이동·공격·승패 판정은 World에서 수행한다.'),
     ('검증 도구', '더미 자동 전투는 반복 부하를 만들고, Redis는 순위를 조회하며, 리플레이는 같은 전투 결과를 다시 확인하는 수단이다.')],
    '사용자는 Game A·B·C 중 하나에 로그인하고 해당 서버 종족의 유닛을 배정받습니다. 이후 World에 새로 접속해 한 유닛을 조작합니다. 화면은 Unreal이 아니라 C++ 리플레이 뷰어이며, 기록된 서버 상태를 복원한 결과입니다. 이 게임 규칙을 배경으로 네트워크·DB·전투 쓰레드가 어떻게 이어지는지를 구현했습니다.',
    [('규칙을 설명하는 순서', '출발 서버의 종족과 저장된 유닛 → World 진입 → 이동·공격·사망 → 원래 서버 복귀와 재입장 대기 → 건물과 승패 순서로 말한다. 서버별 종족은 GameServer.csv로 관리하므로 A=저그는 현재 데이터의 예다.'),
     ('화면 인원과 실제 인원', '뷰어는 많은 유닛을 묶어 그릴 수 있다. 겹친 그림 몇 개가 곧 서버의 실제 유닛 몇 개라는 뜻은 아니다. 전장 상태의 참가자 수와 표시 개수를 구분한다.')],
    [('게임 엔진 없이 무엇을 검증했나요?', '더미의 로그인·이동·공격·스킬, 서버 판정, 사망·복귀, 랭킹, 기록 복원을 확인했다. 최종 엔진 클라이언트의 조작감이나 인터넷 환경 품질까지 검증한 것은 아니다.'),
     ('계정마다 매번 랜덤 유닛인가요?', '처음 배정한 서버별 유닛을 DB에 저장하고 이후 로그인에서는 저장값을 복원한다. 랜덤 배정과 저장된 값 복원의 시점을 나눠 설명한다.')],
    '현재 화면을 실시간 Unreal 클라이언트나 원작 스타크래프트와 동일한 구현으로 설명하지 않는다.',
    [('Data/GameServer.csv', None), ('MultiThreadServer/MultiThreadServer/src/GamePersistence.cpp', 'void CGameLogic::Login('), ('DummyClient/src/ReplayWindow.cpp', 'CReplayWindow::')])

add(3,
    '프로세스와 저장소를 먼저 나눠, 같은 실행 파일을 쓰는 것과 같은 프로세스에서 실행되는 것을 혼동하지 않게 한다. 통신선과 저장 경로는 어느 경계를 넘어 지연·실패가 생기는지도 보여준다.',
    [('Game A/B/C와 World 네 상자', '같은 서버 실행 파일을 서로 다른 설정 인자로 네 번 실행한 별도 프로세스다. 포트와 서버 역할이 달라지고 각 프로세스에 메인·네트워크 쓰레드가 생긴다.'),
     ('MSSQL · Redis · Replay', 'MSSQL은 계정·유닛·세션과 최종 결과, Redis는 경기별 순위 조회, 파일은 전투 기록 복원이라는 서로 다른 책임을 가진다.'),
     ('클라이언트 접속선과 SS_Relay 선', '서버 이동은 클라이언트가 목적지에 새 연결을 여는 경로다. Game↔World 중계 연결은 월드 채팅을 위한 별도 경로다.')],
    '각 Game 서버와 World는 같은 실행 파일을 사용하지만 별도 프로세스로 실행합니다. 클라이언트는 Game에서 이동권을 받은 뒤 World 주소로 새 TCP 연결을 엽니다. 그 아래 저장소도 목적을 나눴습니다. 계정과 세션은 MSSQL, 순위 조회는 Redis, 전투의 과거 상태는 Replay 파일로 관리합니다. 서버 간 채팅 중계선은 이 접속 이동과 별개의 통신입니다.',
    [('선을 따라 질문하기', '각 선마다 누가 시작하고, 어떤 데이터를 보내며, 응답을 어디서 받는지 말한다. DB 선의 뒤에는 DB 쓰레드(워커)가 있고 Redis·파일에도 전용 실행 주체가 있다. 선 하나가 함수 한 번이나 즉시 완료를 뜻하지 않는다.'),
     ('프로세스와 쓰레드의 차이', '프로세스마다 주소 공간이 다르므로 Game의 포인터를 World가 그대로 쓸 수 없다. 이동권과 DB 상태를 통해 필요한 정보를 검증한다. 한 프로세스 안의 객체 참조 관계는 다음 4쪽에서 설명한다.')],
    [('네 서버는 실행 파일도 네 개 만들어야 하나요?', '아니다. 실행 파일 하나를 역할·포트 설정을 달리해 네 프로세스로 실행한다. 운영 배치에 따라 다른 호스트로 분리할 수 있는 경계다.'),
     ('MSSQL 대신 Redis에 전부 저장하지 않은 이유는?', '세션 전이와 계정 저장에는 트랜잭션을 사용하고, 정렬된 순위 조회에는 Redis Sorted Set을 사용했다. 현재 구현의 원본 총계는 World 메모리이며 최종 결과를 별도로 저장한다.')],
    '한 PC의 127.0.0.1 배치는 로컬 검증 구성이다. 이 그림만으로 분산 장애 복구나 다중 호스트 운영이 검증된 것은 아니다.',
    [('MultiThreadServer/MultiThreadServer/src/TcpServer.cpp', 'void RunTcpServer('), ('MultiThreadServer/MultiThreadServer/src/ChatRelay.cpp', 'CChatRelay::'), ('Server.ini', '[World]')])

add(4,
    '상단에 수명 관리 주체를 두고, 왼쪽에 통신 객체, 오른쪽에 게임 상태, 가운데에 공유 채널을 놓았다. 핵심은 데이터 소유권과 연결 관계다. 그림의 모든 화살표를 함수 호출 또는 상속으로 읽으면 안 된다.',
    [('상단 RunTcpServer → 두 클래스', '서버 실행 범위에서 CGameLogic과 네트워크 객체를 구성하고 수명을 유지한다는 관계다. 두 클래스가 부모·자식 상속 관계라는 뜻은 아니다.'),
     ('왼쪽 CIocpServer → stIocpSession', '네트워크 서버가 세션 목록을 관리하고 각 세션이 소켓·수신/송신 버퍼·진행 상태를 가진다. 진행 중 I/O도 shared_ptr로 세션 수명을 보유한다.'),
     ('가운데 채널 ← 세션 / 게임 로직', '각 연결의 stGameChannel 하나를 세션과 stPlayer가 공유한다. 네트워크와 메인이 이 채널로 명령·응답을 이어 주며 A/B/C 서버를 뜻하는 채널은 아니다.'),
     ('오른쪽 CGameLogic → 작업 객체', 'stPlayer·건물·틱·승패의 최종 변경 주체는 메인이다. DB·전투·Redis·기록 작업 객체는 필요한 작업을 분리하되 권한이 모두 같은 것은 아니다.')],
    '이 장은 상속도가 아니라 객체가 가진 상태와 연결 관계입니다. 왼쪽 세션은 소켓과 통신 버퍼를, 오른쪽 게임 로직은 플레이어와 전장 상태를 관리합니다. 가운데 채널은 같은 연결의 세션과 플레이어가 공유하는 우편함입니다. 게임 로직이 소켓을 직접 조작하지 않고 완성 응답을 채널에 넣으면 네트워크가 가져갑니다. 아래 작업 객체는 DB·계산·랭킹·기록을 분리한 실행 단위입니다.',
    [('현재 변수명과 축약 표기', '그림의 workers/sessions는 CIocpServer의 m_workers/m_sessions를 간단히 적은 것이다. 채널 상자의 sendMutex는 송신 큐를, 세션의 sessionMutex는 수신·송신 진행 상태를 보호한다. 그림의 shared_ptr<stGameChannel> 필드는 sp_channel이다.'),
     ('연결 식별과 계정 식별', 'm_players는 stGameChannel*를 키로 현재 연결의 stPlayer를 찾고, m_playersById는 계정의 player ID로 전장 대상을 찾는다. 네트워크 세션 id는 연결마다 부여되며 DB 계정 ID와 수명·목적이 다르다. 같은 채널을 공유하기 때문에 이동 요청의 주인을 전체 1,500명 순회 없이 찾을 수 있다.')],
    [('CGameLogic이 stIocpSession을 상속하나요?', '아니다. 역할이 다른 객체이며 공통 채널을 참조한다. 그림의 화살표는 상속 문법이 아니라 수명 관리·보유·공유 연결을 설명한다.'),
     ('채널을 shared_ptr로 두면 내부도 쓰레드 안전한가요?', '객체 수명만 함께 유지한다. sendQueue 등 복합 상태는 sendMutex, connected 같은 개별 값은 atomic으로 보호한다. 자세한 보충은 뒤의 객체·수명 해설에서 다룬다.')],
    '객체 상자 하나를 쓰레드 하나로 읽지 않는다. Game A/B/C 프로세스 그림, 객체 관계 그림, 쓰레드 그림은 서로 다른 관점이다.',
    [('MultiThreadServer/MultiThreadServer/src/IocpSession.h', 'struct stIocpSession'), ('MultiThreadServer/MultiThreadServer/src/GameLogic.h', 'struct stGameChannel'), ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'auto& player = m_players[')],
    ('MultiThreadServer/MultiThreadServer/src/IocpSession.h', 'struct stIocpSession', 'CSocket socket;', 7))

add(5,
    '객체 관계도 다음에 실행 주체를 따로 그려, 어떤 함수가 어느 쓰레드에서 실행되는지 보여준다. 금색 전달선과 청록 결과선을 분리한 이유는 요청 등록과 결과 반영이 같은 순간이 아니기 때문이다.',
    [('Network → Main', 'IOCP 쓰레드(워커)는 수신·프레임 복원 뒤 m_commands에 명령을 넣는다. 메인이 큐에서 꺼내 실제 게임 규칙을 처리한다.'),
     ('Main ↔ Battle', '메인이 계산 함수를 게시하고 전투 쓰레드(워커)가 독립 결과 칸을 채운다. 메인은 완료를 기다리므로 이 대기 자체가 틱 지연의 일부다.'),
     ('DB / Replay / Redis', '외부 I/O를 전용 쓰레드로 분리한다. DB·순위 조회는 결과 큐로 돌아오고, 기록은 파일 쓰기 실패·완료 상태를 따로 관리한다.')],
    'World 기본 설정 예시에서는 네트워크 2, 메인 1, 전투 4, DB 2, 기록 1, Redis 1로 명시적 쓰레드가 11개입니다. 숫자보다 중요한 것은 상태를 쓰는 주체입니다. 메인은 플레이어·HP·킬·승패를 확정하고 다른 쓰레드는 통신, 계산 결과, DB 결과를 넘깁니다. DB 응답 대기를 메인 밖으로 뺀 것과 전투 계산 완료를 메인이 기다리는 것은 구분해서 봐야 합니다.',
    [('11개가 의미하는 범위', 'World의 현재 기본값을 설명한 수다. Game 프로세스는 World와 생성되는 작업 객체가 다르고, 부하 시연은 Network 4·DB 6 같은 실행 사본을 사용했다. 라이브러리나 운영체제 내부 쓰레드까지 모두 센 값도 아니다.'),
     ('큐와 장벽을 구분', 'm_commands와 DB 큐에는 요청이 대기할 수 있다. CBattleWorkers에는 계산 묶음을 끝없이 추가하는 별도 큐가 없다. Run이 전체 완료를 기다린 뒤 반환한다. 외부 저장 I/O는 이 장벽에 포함되지 않는다.')],
    [('쓰레드 수가 많으면 무조건 유리한가요?', '아니다. 스케줄링·동기화·메모리 비용이 늘고 직렬 구간은 남는다. 실제 이득은 뒤의 조건별 지표로 확인했다.'),
     ('메인이 계산을 기다리는 동안 새 입력은?', 'IOCP 쓰레드가 m_commands에 등록할 수 있으나 메인은 계산 반환 뒤에 다시 처리한다. 그래서 계산 시간이 길면 입력 지연과 큐 적체에도 영향을 준다.')],
    '그림의 workers는 서로 다른 역할이다. 설명에서는 IOCP 쓰레드(워커), 전투 쓰레드(워커), DB 쓰레드(워커)로 구분한다.',
    [('Server.ini', '[Battle]'), ('MultiThreadServer/MultiThreadServer/src/BattleWorkers.cpp', 'void CBattleWorkers::Run('), ('MultiThreadServer/MultiThreadServer/src/DatabaseWorker.cpp', 'void CDatabaseWorker::Run()')])

add(6,
    '서버 시작과 접속 완료를 한 줄의 단계로 보여주되 실제 코드는 접속 완료 부분만 발췌했다. 생성자 실행과 새 IOCP 쓰레드 실행, AcceptEx 등록과 접속 완료를 구분해서 읽게 하는 장이다.',
    [('설정 로드 → listen 준비', 'INI·CSV 유효성을 확인한 뒤 주소와 포트를 묶고 대기 소켓을 연다. 데이터가 잘못됐는데 정상 기동한 것처럼 보이지 않도록 시작 단계에서 검사한다.'),
     ('IOCP 시작 → AcceptEx 등록', '완료 포트와 네트워크 쓰레드를 만들고 접속 수락 작업을 미리 등록한다. 최대 8개는 대기 Accept 작업 수이며 전체 접속 인원 제한이 아니다.'),
     ('HandleAccept → PostRecv', '완료된 소켓의 옵션을 설정하고 새 세션 ID와 완료 포트 연결을 만든다. notifySend 콜백을 연결한 뒤 첫 수신을 등록한다.')],
    '처음에는 메인이 설정과 데이터를 준비하고 listen 소켓을 엽니다. IOCP 서버를 만들면 접속 수락 작업을 미리 등록하고 완료 통지를 기다릴 쓰레드들을 실행합니다. 접속 완료는 HandleAccept에서 처리하며 세션을 만든 뒤 완료 포트에 연결합니다. 마지막으로 게임 응답용 알림을 세션 ID와 연결하고 PostRecv로 첫 수신을 등록합니다.',
    [('세션 ID를 캡처하는 이유', 'notifySend는 나중에 게임 로직이 호출한다. 콜백은 세션 포인터 자체 대신 id를 사용해 완료 포트에 알림을 보낸다. 네트워크가 알림을 꺼냈을 때 세션 목록에서 id를 다시 확인할 수 있다.'),
     ('등록·완료·재등록', 'PostAccept는 요청 등록, HandleAccept는 완료 처리다. 완료된 I/O 객체는 반환하고 이후 PostAccept로 대기 작업을 보충한다. 풀 여유와 연결 상한에 따라 등록이 제한될 수 있다.')],
    [('AcceptEx를 8개 걸면 8명만 접속하나요?', '아니다. 미리 대기하는 접속 작업을 최대 8개 유지하는 것이고 완료 후 다시 보충한다. 실제 접속 수용 제한은 별도 설정과 검사에 따른다.'),
     ('PostRecv를 호출하면 로그인까지 끝나나요?', '아니다. 수신 버퍼를 등록한 단계다. 데이터가 도착한 뒤 버전 검사와 CM_JoinGame의 계정 처리로 이어진다.')],
    '그림의 한 단계가 한 쓰레드를 뜻하지 않는다. 생성자는 메인, 완료 처리는 IOCP 쓰레드에서 실행된다.',
    [('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::HandleAccept('), ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::PostAccept()')],
    ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::HandleAccept(', 'sp_session->sp_channel->notifySend =', 8))

add(7,
    '수신 등록 코드를 크게 보여주고 오른쪽에 결과·완료·다음 등록을 배치했다. 비동기 호출은 데이터를 즉시 반환하는 일반 함수 호출과 다르며 버퍼 수명이 완료까지 이어진다는 점을 설명한다.',
    [('풀에서 가져온 p_operation', 'OVERLAPPED와 4096바이트 버퍼, 작업 종류, 세션 참조를 가진 I/O 객체다. 요청이 진행되는 동안 주소를 유지한다.'),
     ('WSARecv와 WSA_IO_PENDING', 'Windows에 수신을 등록한다. SOCKET_ERROR와 함께 WSA_IO_PENDING이 나오면 비동기 대기 중인 정상 등록이며 그 외 즉시 오류와 구분한다.'),
     ('GQCS → 누적 → PostRecv', '실제 받은 bytes만 recvBuffer에 추가한다. 한 번의 완료가 한 패킷이라는 보장은 없으므로 프레임 복원 뒤 다음 수신을 등록한다.')],
    'PostRecv는 데이터를 받았다는 뜻이 아니라 받을 공간을 Windows에 맡기는 함수입니다. 작업 객체에 세션 참조를 넣고 고정 버퍼와 OVERLAPPED를 넘깁니다. 나중에 Run의 GQCS가 완료를 꺼내면 받은 길이만큼 누적합니다. 게임 패킷은 명령 큐로 넘기고 다음 수신을 등록합니다. 작업 객체는 완료 처리가 끝난 뒤 풀에 반환합니다.',
    [('원문에서 확인할 두 지점', 'PostRecv의 WSARecv 호출과 Run의 GetQueuedCompletionStatus를 나란히 본다. 같은 overlapped 주소가 등록과 완료를 연결한다. recvBuffer는 처리되지 않은 TCP 바이트를 보관하는 문자열이며 OS에 맡긴 고정 버퍼와 다르다.'),
     ('연결당 수신 하나의 효과', '같은 세션의 다음 수신은 이전 완료 처리 후에 등록한다. 여러 세션은 병렬로 진행할 수 있고 같은 세션의 송신·수신 완료는 서로 다른 IOCP 쓰레드에 배정될 수 있어 sessionMutex를 사용한다.')],
    [('왜 처음부터 recvBuffer의 주소를 넘기지 않았나요?', '문자열을 append하거나 erase하면 주소가 바뀔 수 있다. 완료 전까지 주소가 유지되는 I/O 객체 버퍼를 사용하고 완료 후 누적 문자열로 옮긴다.'),
     ('수신 완료에서 Player를 바로 움직이나요?', '프레임 분리·시스템 검사까지 수행하고 게임 요청은 Submit에 넣는다. 실제 이동 요청 검증과 상태 변경은 메인 경로다.')],
    '수신 준비가 됐을 때 recv를 호출하는 WSAPoll 경로와, 미리 WSARecv를 등록하고 완료를 받는 IOCP 경로를 섞어 설명하지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::PostRecv('), ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::HandleSessionCompletion(')],
    ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::PostRecv(', 'p_operation->sp_session = sp_session;', 9))

add(8,
    '여러 파일의 함수가 하나의 요청에서 어떻게 이어지는지 보여주는 지도다. 화살표를 지그재그로 배치해 클라이언트 입력 → 서버 처리 → 클라이언트 수신의 왕복을 한 장에 담았다.',
    [('1~3: 직렬화와 수신 프레임', '클라이언트는 MoveRequest를 바이트로 만들고 서버는 TCP 누적 데이터에서 완성된 프레임을 찾는다. 프레임 분리와 Protobuf 역직렬화는 다른 단계다.'),
     ('4~6: 명령 큐와 게임 응답', 'Submit 이후 메인이 HandlePacket·HandleWorldPacket·HandleMove로 목표를 설정한다. 수락 응답을 생성해 송신 큐에 넣는다.'),
     ('7~9: 송신 알림과 클라이언트', '완료 포트 알림으로 송신을 유도하고 PostSend가 비동기 송신을 등록한다. 클라이언트 수신 쓰레드는 일반 응답과 WorldState 조각을 구분한다.')],
    'CM_Move 하나를 기준으로 전체 경로를 보겠습니다. 클라이언트에서 좌표를 직렬화해 보내면 IOCP가 수신 완료를 받고 프레임을 복원합니다. 게임 명령은 Submit에 등록되고 메인이 목표 좌표를 바꿉니다. 그 뒤 수락 응답을 송신 큐로 넘기고 IOCP가 전송합니다. 실제 위치 변화는 다음 전장 Tick에서 계산된 뒤 별도의 WorldState로 내려갑니다.',
    [('두 종류의 결과', 'SM_ActionReply는 요청을 받아들였다는 결과이며 이동이 끝났다는 뜻이 아니다. SM_WorldState에는 이후 틱의 실제 좌표가 들어간다. 클라이언트에서 요청 응답과 지속 상태 갱신을 같은 패킷으로 가정하지 않는다.'),
     ('쓰레드 전환 표시', '1은 클라이언트 호출 쪽, 2~3은 IOCP, 4는 큐 경계, 5~6은 주로 메인, 7~8은 IOCP 경로다. 도형 사이에 큐가 있으면 호출 스택 하나로 끝까지 실행되는 구조가 아니라는 점을 짚는다.')],
    [('Move가 들어오면 좌표는 언제 바뀌나요?', 'HandleMove에서는 goalX/goalY와 moving을 설정한다. 실제 x/y는 Tick의 MovePlayers 결과를 메인이 반영할 때 바뀐다.'),
     ('SYS_Ping도 전투 큐를 통과하나요?', '아니다. 시스템 Ping은 네트워크 경로에서 응답한다. 따라서 낮은 Ping RTT만으로 메인 게임 로직이 빠르다고 결론 낼 수 없다.')],
    '원본의 CM_Move=18, ActionReply=21, WorldState=22는 현재 Packet.h의 순서 기반 번호다. 본문 필드 번호와 섞지 않는다.',
    [('DummyClient/src/ClientConnection.cpp', 'CClientConnection::Request('), ('MultiThreadServer/MultiThreadServer/src/PacketDispatch.cpp', 'void HandleClientPackets('), ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::HandleMove(')])

add(9,
    'TCP가 메시지 경계를 보존하지 않는다는 문제를 수신 조각 세 개로 시각화했다. 아래 코드의 break와 마지막 erase가 각각 불완전 보관과 처리 완료 데이터 제거를 담당함을 연결해서 설명한다.',
    [('수신 #1~#3', '헤더 한 바이트만 오거나, 본문 일부만 오거나, 본문 끝과 다음 패킷 전체가 한꺼번에 올 수 있다. 송신 호출 횟수와 수신 완료 횟수는 일치하지 않는다.'),
     ('4바이트 공통 헤더', '전체 길이 2바이트와 종류 2바이트다. 길이는 헤더를 포함하고 4~4096 범위를 검사한다. 타입 번호를 확인한 뒤 본문 범위를 잡는다.'),
     ('consumed와 recvBuffer.erase', '처리한 길이만 누적하고 마지막에 해당 구간을 지운다. 남은 불완전 데이터는 다음 수신과 연결한다.')],
    'TCP에서 받은 바이트를 바로 패킷 하나로 해석하면 분할·병합 수신에서 깨집니다. 그래서 세션 문자열에 누적한 뒤 헤더의 길이를 읽습니다. 헤더가 부족하거나 전체 본문이 아직 안 왔으면 기다리고, 완성된 프레임만 처리합니다. 마지막에 소비한 앞부분만 지워 다음 프레임의 일부가 손실되지 않게 했습니다.',
    [('숫자로 직접 설명하기', '전체 길이 20인 패킷이 7바이트만 왔다면 13바이트를 더 기다린다. 누적 데이터 44바이트에 길이 20짜리와 24짜리 패킷이 있으면 두 번 처리한다. 단, 길이 필드 자체가 허용 범위를 벗어나면 기다리지 않고 잘못된 프레임으로 처리한다.'),
     ('패딩과 직렬화', 'C++ 구조체 메모리를 통째로 전송하지 않고 Read16/Append16으로 헤더를 조립한다. 따라서 구조체 정렬을 위해 헤더에 빈 바이트를 넣을 필요가 없다. Protobuf 본문의 인코딩은 이 big-endian 헤더 규칙과 별개다.')],
    [('패킷 분리가 곧 역직렬화인가요?', '아니다. 프레임 분리는 바이트에서 길이·종류·본문 범위를 찾는 작업이고, ParseFromArray 등은 본문을 MoveRequest 같은 객체로 복원하는 작업이다.'),
     ('한 번 recv에 패킷 세 개가 오면?', '완성된 프레임이 남아 있는 동안 루프를 반복한다. 마지막 패킷이 일부만 왔으면 그 부분은 누적 문자열에 보관한다.')],
    '4~4096은 현재 구현의 선택이다. TCP 자체가 4096바이트 메시지만 지원한다는 의미가 아니다.',
    [('MultiThreadServer/MultiThreadServer/src/Packet.h', 'inline size_t PacketSize('), ('MultiThreadServer/MultiThreadServer/src/PacketDispatch.cpp', 'void HandleClientPackets(')],
    ('MultiThreadServer/MultiThreadServer/src/PacketDispatch.cpp', 'void HandleClientPackets(', 'const size_t size = Protocol::PacketSize', 6))

add(10,
    '번호·본문·허용 목록·처리·클라이언트 연결을 표의 다섯 행으로 나눈 이유는 새 패킷을 추가할 때 놓치기 쉬운 수정 위치를 명시하기 위해서다. 이름이 비슷한 숫자의 의미도 분리한다.',
    [('Packet.h의 Protocol::Type', '패킷 종류 번호다. SYS 1~4를 사용하고 5~9는 예약하며 CM_JoinGame=10부터 게임 번호가 연속된다.'),
     ('Game.proto의 MoveRequest', '본문 x와 y의 타입 및 필드 번호를 정의한다. double x=1의 1은 메시지 안의 필드 태그이지 패킷 번호 1이 아니다.'),
     ('허용 → 처리 → 사용', '수신 허용에 추가해야 큐로 전달되고, 게임 처리 분기에서 규칙을 구현해야 한다. 더미도 같은 ID와 생성 메시지로 요청·응답을 사용해야 한다.')],
    '패킷을 추가할 때는 다섯 곳을 연결해서 봅니다. Packet.h가 메시지 종류를, proto가 본문 구조를 정합니다. PacketDispatch에서는 받을 수 있는 종류인지 확인하고, CGameLogic이 실제 요청을 처리합니다. 마지막으로 더미에서 같은 요청과 응답을 사용합니다. 현재는 흐름이 보이도록 명시적 분기를 사용했고 자동 등록 프레임워크를 추가하지 않았습니다.',
    [('번호가 연속인 enum의 주의점', '중간에 항목을 삽입하면 뒤 번호가 바뀔 수 있다. 기존 호환성을 유지하려면 현재 규칙대로 끝에 추가하고 클라이언트·서버·기록 버전을 함께 확인한다. 연속 번호를 쓴다는 사실이 버전 호환성을 자동 해결하지는 않는다.'),
     ('자동 생성 코드의 위치', 'Game.pb.h/.cc는 protoc 산출물이다. 새 필드를 추가할 때 원본 proto를 바꾸고 빌드의 생성 단계를 사용한다. 생성 코드에 직접 로직이나 개인 접두사 규칙을 넣지 않는다.')],
    [('CM_/SM_/SS_/SYS_의 차이는?', 'CM은 클라이언트→서버, SM은 서버→클라이언트, SS는 서버 사이 중계, SYS는 통신 점검용 메시지다. 분류 이름이지 다른 전송 프로토콜을 뜻하지 않는다.'),
     ('ParseFromArray는 직접 만든 함수인가요?', 'protoc로 생성된 메시지가 제공하는 Protobuf API다. 프로젝트는 호출 후 게임 규칙 검증을 추가한다. 직렬화 구현을 모든 메시지마다 직접 작성하지 않는다.')],
    '표의 HandlePacket은 진입점을 축약한 이름이다. 현재 Move 본문은 HandleWorldPacket에서 파싱한 뒤 HandleMove로 전달한다.',
    [('MultiThreadServer/MultiThreadServer/src/Packet.h', 'enum class Type'), ('Protocol/Game.proto', 'message MoveRequest'), ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::HandleWorldPacket(')],
    ('Protocol/Game.proto', 'message MoveRequest', 'message MoveRequest', 1))

add(11,
    '시스템 패킷과 게임 패킷의 경계를 나눠, 통신 준비 확인과 계정 로그인·게임 규칙 검증을 같은 단계로 오해하지 않게 했다. 코드 상자는 전체 구현이 아니라 분기 구조를 요약한다.',
    [('첫 접속의 버전 검사', 'client_name 길이와 protocol_version=5를 확인한다. 성공 시 versionChecked를 설정하고 시작 때 만든 서버 정보 패킷을 응답한다.'),
     ('시스템 Ping과 게임 요청', 'Ping은 네트워크 경로에서 검사하고 응답한다. 게임 패킷은 허용된 종류만 Submit으로 넘겨 메인이 처리한다.'),
     ('형식 오류와 게임 규칙 위반', '깨진 헤더·잘못된 타입·버전 같은 통신 오류와, 정상 요청이지만 이동 불가·MP 부족인 게임 거부를 구분한다.')],
    '먼저 이 연결이 현재 통신 규칙을 사용하는지 확인합니다. 버전 검사는 계정 로그인과 별도이며, 통과한 연결만 다음 요청을 받습니다. Ping은 네트워크 경로에서 바로 답하고 게임 요청은 명령 큐로 넘깁니다. Protobuf 파싱이 성공해도 좌표나 게임 상태가 올바르다는 뜻은 아니어서 메인에서 다시 규칙을 검사합니다.',
    [('Parse 성공의 한계', '정해진 형식으로 double이나 정수를 읽었다고 맵 안의 좌표, 로그인한 계정, 사용할 수 있는 스킬이라는 보장은 없다. 형식 → 값 범위 → 연결/세션 자격 → 게임 상태 순서로 검증 책임을 나눈다.'),
     ('요약 코드와 실제 코드', '원본 상자는 긴 Protocol::Type 접두사와 전체 허용 목록을 줄였다. 실제 코드는 if/else와 ParseFromArray·예외 처리를 포함한다. 그대로 복사해 컴파일할 코드라고 소개하지 않는다.')],
    [('버전을 왜 매 패킷 헤더에 안 넣나요?', '현재는 접속 직후 한 번 검사하는 단순한 구조를 택했다. 공통 헤더는 길이·종류만 가지며 이후 연결 상태를 기준으로 게임 요청을 허용한다.'),
     ('서버 버전 확인이 성공하면 로그인한 건가요?', '아니다. 통신 형식 확인이고, 계정 ID·비밀번호 인증과 DB 세션 생성은 CM_JoinGame 경로에서 진행한다.')],
    '버전 검사는 암호화·사용자 인증을 대신하지 않는다. TLS를 구현했다고 주장하지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/PacketDispatch.cpp', 'void HandleClientPackets('), ('Protocol/Game.proto', 'message ServerVersionCheckRequest')],
    ('MultiThreadServer/MultiThreadServer/src/PacketDispatch.cpp', 'void HandleClientPackets(', 'if (request.protocol_version()', 6))

add(12,
    '입력 큐 코드와 복사·상한·종료 연결 설명을 나란히 두어, 메인 소유권을 실제로 유지하는 경계가 어디인지 보여준다. 큐를 쓴다는 사실보다 큐에 무엇을 보관하고 언제 잠금을 푸는지가 핵심이다.',
    [('m_commandsMutex', 'IOCP 쓰레드의 push와 메인의 pop을 같은 잠금으로 보호한다. 큐 자체에 lock 기능이 있는 것이 아니라 별도 mutex로 접근 규칙을 지킨다.'),
     ('string(payload)와 sp_channel', '본문은 독립 문자열로 복사하고 연결 우편함은 shared_ptr로 유지한다. 나중에 수신 문자열이 바뀌거나 연결이 정리돼도 참조 수명과 본문이 안전해야 한다.'),
     ('2048 / 32 / 128', '전체 대기 명령·연결별 대기 명령 상한과 한 번 Update가 꺼내는 처리 예산이다. 전투 유닛 수나 IOCP 쓰레드 수가 아니다.')],
    'IOCP 쓰레드는 게임 상태를 직접 고치지 않고 명령을 큐에 넣습니다. 본문은 string_view 그대로 보관하지 않고 복사합니다. 메인은 한 번에 최대 128개를 지역 work로 옮긴 뒤 잠금을 풀고 처리합니다. 큐 교환 중에만 잠그기 때문에 긴 HandlePacket 실행 동안에도 네트워크가 새 명령을 넣을 수 있습니다.',
    [('move와 pop_front', 'work.push_back(move(m_commands.front()))는 원소의 문자열·스마트 포인터를 이동하고, 이어지는 pop_front가 큐 원소를 제거한다. move만으로 큐 크기는 줄지 않는다. 현재 stCommand는 복사도 가능하지만 곧 버릴 원본이므로 이동으로 복사 비용을 줄인다.'),
     ('상한이 필요한 이유와 한계', '메인 처리보다 입력이 빨라지면 큐가 늘어난다. 상한은 무한 메모리 증가를 막지만 요청을 모두 무조건 처리한다는 보장은 아니다. Submit에서 상한을 넘으면 예외가 네트워크 오류 경로로 이어져 연결이 정리될 수 있다. 현재 구현을 입력 시각 기준 공정성 보장이라고 설명하지 않는다.')],
    [('왜 큐를 잠그지 않고 뮤텍스를 잠그나요?', 'deque에는 lock/unlock이 없다. 같은 큐를 쓰는 모든 코드가 m_commandsMutex를 잠그도록 해서 보호한다.'),
     ('서버가 입력보다 느리면 TCP가 다 해결하나요?', 'TCP 전달과 응용 명령 처리 능력은 별개다. 소켓 버퍼·흐름 제어가 지연을 만들 수 있고 응용 큐 상한에 도달하면 현재 서버는 연결을 정리할 수 있다.')],
    'Update마다 128개라는 값은 초당 128개 제한이 아니다. Update는 메인 루프에서 반복 호출된다.',
    [('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::Submit('), ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::Update()')],
    ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::Update()', 'for (int i = 0;', 5))

add(13,
    '수락 응답과 실제 이동 결과를 세 단계로 나눈 이유는 네트워크 패킷 도착 즉시 좌표를 순간 이동시키는 구조가 아님을 보여주기 위해서다. 화면은 입력 승인과 전장 상태 갱신을 분리해서 따라간다.',
    [('자격 확인', 'World 입장·DB 작업·lease·락다운·버로우 등 현재 상태를 확인한다. 정상 형식의 패킷이어도 요청을 거부할 수 있다.'),
     ('goalX / goalY / moving', '서버가 받아들인 목적지를 보관한다. 여기서 바뀌는 목표 값과 현재 unit.x/y를 구별한다. 이동 요청은 지속 치료 상태도 해제한다.'),
     ('Tick의 MovePlayers', '속도와 맵·건물 조건을 이용해 한 틱 이동 결과를 계산한 뒤 메인이 반영한다. 이후 Snapshot으로 좌표가 클라이언트에 전달된다.')],
    'CM_Move를 받으면 먼저 이동 가능한 상태인지 검사하고 목적지를 저장합니다. ActionReply는 그 목적지를 받아들였다는 응답입니다. 실제 좌표는 전장 Tick의 이동 계산 결과로 갱신합니다. 그래서 요청 하나와 좌표 한 번 변경을 직접 대응시키지 않고, 목적지와 서버 시간 진행을 분리했습니다.',
    [('누구를 움직일지 찾는 경로', '명령에는 연결 채널이 들어 있고 Update에서 m_players[command.sp_channel.get()]으로 해당 플레이어를 찾는다. HandleMove가 그 stPlayer를 참조로 받아 목표를 바꾼다. 전장 대상 조회용 m_playersById와도 역할이 다르다.'),
     ('충돌과 길찾기 범위', '현재 이동 계산은 맵 경계·건물에 대한 CanStand 검사 등을 사용하며, 유닛 사이 물리 충돌과 범용 길찾기를 구현한 것은 아니다. 여러 유닛이 한 지점에 겹칠 수 있다는 한계를 그대로 설명한다.')],
    [('목표를 바꾼 뒤 누가 이동하나요?', '다음 Tick에서 그 플레이어의 이동 입력을 만들고 전투 쓰레드가 결과를 계산한다. 메인이 결과를 실제 unit에 반영한다.'),
     ('클라이언트가 현재 좌표를 보낸 대로 믿나요?', '현재 요청은 목적지다. 서버가 범위·상태를 검증하고 자신의 좌표·속도로 실제 이동을 계산한다. 클라이언트가 임의로 현재 위치를 덮어쓰는 구조가 아니다.')],
    '수락 응답의 빠름과 실제 이동 표시 지연은 다르다. Snapshot 주기도 함께 고려해야 한다.',
    [('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::HandleMove('), ('MultiThreadServer/MultiThreadServer/src/BattleCalculation.cpp', 'stMovementResult CalculateMovement(')],
    ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::HandleMove(', 'player.goalX = request.x();', 6))

add(14,
    '응답은 수신 직후뿐 아니라 DB 완료·Tick에서도 생기므로, 게임 로직이 만든 데이터를 네트워크 쓰레드에 알리는 경로를 별도 그림으로 보였다. 큐 적재와 실제 송신 등록 사이에 깨우기 단계가 있다.',
    [('SendMessage → SendPacket', '일반 응답 경로에서 Protobuf 직렬화와 헤더 조립을 한 뒤 완성 바이트를 채널의 sendQueue에 넣는다. 병렬 Snapshot은 이미 완성된 패킷을 SendPacket에 넘긴다.'),
     ('notifySend와 중복 알림', 'sendMutex 안에서 notifySend와 sendNotifyPending을 함께 관리해 같은 대기 구간의 알림을 묶는다. PostSend가 큐를 가져올 때 다음 알림을 허용한다.'),
     ('PostQueuedCompletionStatus → GQCS', '이 알림의 OVERLAPPED는 nullptr이고 key에 세션 ID가 들어간다. 실제 Send I/O 완료와 같은 완료 포트로 오지만 구분해서 처리한다.')],
    '메인이 응답을 만들었다고 IOCP 쓰레드가 저절로 깨어나는 것은 아닙니다. 채널의 송신 큐에 넣은 뒤 notifySend를 호출해 완료 포트에 알림을 보냅니다. Run은 I/O 객체가 없는 알림임을 확인하고 세션 ID로 현재 연결을 찾은 뒤 PostSend를 호출합니다. 덕분에 수신이 없어도 DB 결과나 틱 상태를 보낼 수 있습니다.',
    [('락 범위', 'sendQueue에 추가하고 대기 바이트를 갱신하며 알림 상태를 검사하는 부분은 같은 sendMutex로 보호한다. 큐를 가져가는 PostSend도 같은 잠금을 사용한다. atomic 하나로 이 여러 상태의 관계를 대신하지 않는다.'),
     ('늦게 도착한 알림', '알림이 만들어진 직후 연결이 종료될 수 있다. 알림에는 포인터를 직접 실어 나르지 않고 ID를 사용하므로, Run에서 m_sessions를 조회해 없으면 처리하지 않는다. 콜백은 CloseSession에서 해제한다.')],
    [('SendPacket은 실제 send 함수인가요?', '완성 바이트를 응답 큐에 적재하는 함수다. 실제 Windows 송신 등록은 PostSend의 WSASend다.'),
     ('모든 직렬화가 메인에서 실행되나요?', '일반 SendMessage 경로는 호출한 실행 주체에서 직렬화한다. BroadcastWorldState는 전투 쓰레드가 수신자별로 직렬화하고 메인이 완성 바이트를 큐에 넣는다.')],
    '완료 포트의 사용자 알림과 실제 송신 완료를 구분한다. WSAPoll은 같은 notifySend 방식 대신 다음 순회에서 큐를 확인한다.',
    [('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::SendPacket('), ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::NotifySend(')],
    ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::SendPacket(', 'sp_channel->sendQueue.push_back(', 7))

add(15,
    '송신 데이터를 세 저장 공간으로 나눠 그려, 큐가 비었다는 사실과 네트워크 전송 완료를 혼동하지 않게 했다. 완료 바이트만 지우는 코드로 부분 송신과 버퍼 수명 문제를 설명한다.',
    [('sendQueue → sendBuffer', 'PostSend가 큐의 모든 패킷을 연결별 문자열에 이어 붙인 후 sendQueue.clear()한다. 실제 전송 전이어도 별도 버퍼에 내용이 남아 있으므로 안전하다.'),
     ('sendBuffer → I/O 고정 버퍼', '현재 전송할 구간에서 최대 4096바이트를 memcpy로 복사한다. 원래 문자열이 나중에 바뀌어도 Windows가 사용하는 I/O 버퍼 주소는 유지된다.'),
     ('WSASend → 완료 → erase', 'sendPending으로 연결당 실제 송신 한 개를 유지한다. GQCS 완료의 bytes만 sendBuffer에서 소비하고 남은 데이터는 다음 PostSend가 등록한다.')],
    '여기서는 큐를 비우는 시점과 송신 완료를 구분해야 합니다. 큐의 패킷을 sendBuffer로 모두 옮겼기 때문에 큐는 먼저 clear합니다. 그 뒤 I/O 객체에 전송 구간을 복사하고 WSASend를 등록합니다. Windows가 완료를 알려주면 그 바이트 수만큼 sendBuffer에서 지우고 다음 송신을 이어갑니다. sendPending=false는 완료 통지를 받은 뒤 코드가 설정합니다.',
    [('한 연결의 순서 유지', '진행 중 sendPending이 true이면 새 패킷을 sendBuffer에 합치더라도 두 번째 WSASend를 겹쳐 등록하지 않는다. 실제 전송 대기 순서가 유지된다. 다른 연결 사이의 전역 송신 순서나 공정성을 보장하는 구조는 아니다.'),
     ('완료의 의미', 'WSASend 반환이 클라이언트 게임 로직의 처리 완료를 뜻하지 않는다. I/O 완료도 상대 응용 코드가 내용을 사용했다는 확인 응답과 다르다. 게임 차원의 처리 확인이 필요하면 별도의 응답·시퀀스 규칙이 필요하다.')],
    [('sendQueue에 패킷이 여러 개면 왜 clear하나요?', 'for문이 큐 전체를 sendBuffer에 옮긴 뒤이기 때문이다. 옮기는 동안 같은 sendMutex를 잠가 중간에 추가된 새 패킷이 함께 지워지는 상황을 막는다.'),
     ('많이 쌓인 연결이 다른 연결을 늦출 수 있나요?', '가능하다. 비동기 전송 완료까지 쓰레드가 기다리지는 않지만 큐 병합·복사 시간은 소비한다. 현재는 대기 바이트 상한이 있고 연결별 균등 처리 예산까지 구현한 것은 아니다.')],
    'sendQueue가 비었음, WSASend 등록 성공, I/O 완료, 클라이언트 처리 완료는 각각 다른 시점이다.',
    [('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::PostSend('), ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::HandleSessionCompletion(')],
    ('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::PostSend(', 'memcpy(', 4))

add(16,
    '닫기·취소·완료 회수·쓰레드 종료를 시간 순서로 배치했다. 소켓을 닫는 것만으로 OS가 맡고 있던 모든 작업과 객체 사용이 끝나는 것은 아니므로, 종료 순서가 설계의 일부임을 보여준다.',
    [('CloseSession / Cancel', 'closed와 채널 연결 상태를 바꾸고 알림을 해제하며 CancelIoEx·소켓 해제를 수행한다. 세션 목록에서 빠져도 진행 중 작업의 참조가 남을 수 있다.'),
     ('잔여 완료 회수', '각 stIoOperation의 shared_ptr가 세션을 유지한다. 실패·취소 완료도 IOCP에서 회수한 뒤 ReleaseOperation으로 작업을 반환한다.'),
     ('outstanding=0 → 종료 알림 → join', '대기 작업이 남아 있는데 완료 처리 쓰레드를 먼저 없애지 않는다. 잔여 작업 수를 확인한 뒤 쓰레드를 깨워 종료시키고 합류한다.')],
    '연결을 닫는 것과 그 연결의 모든 비동기 작업을 정리한 것은 다릅니다. 세션 목록에서는 먼저 제거할 수 있지만 진행 중 I/O가 shared_ptr로 수명을 보유합니다. 완료 통지를 회수한 뒤 I/O 객체의 참조를 놓고 풀로 반환합니다. 서버 종료도 이 잔여 작업이 끝나기 전에 IOCP 쓰레드를 멈추지 않는 순서로 구성했습니다.',
    [('shared_ptr가 담당하는 범위', '수명은 세션 목록·I/O 객체·Run의 지역 shared_ptr가 함께 유지한다. 풀 반환의 reset 하나가 곧바로 세션 삭제를 의미하지 않으며 마지막 참조가 없어질 때 삭제된다. sessionMutex와는 역할이 다르다.'),
     ('검증 수치의 범위', 'pending_io=0과 pool_in_use=0은 측정한 종료 시점의 잔여 작업·블록이 없다는 확인이다. 모든 자원의 메모리 누수 검사가 끝났다는 뜻이나 어떤 OS 장애에서도 유한 시간 종료가 보장된다는 뜻으로 확대하지 않는다.')],
    [('목록에서 지운 세션으로 완료가 오면 위험하지 않나요?', 'I/O 객체가 그 세션을 shared_ptr로 보관한다. Run도 처리 중 참조를 갖고 closed이면 추가 게임 처리를 하지 않으면서 작업 회수는 진행한다.'),
     ('IOCP 쓰레드를 먼저 join하면?', '아직 완료를 회수해야 할 작업이 남으면 종료를 기다리는 쪽이 진행하지 못할 수 있다. 그래서 완료를 처리할 실행 주체를 잔여 작업 회수까지 유지한다.')],
    '현재 Stop은 outstanding이 0이 될 때까지 기다리는 구조다. 임의의 운영체제 장애에 대한 강제 종료·시간 제한 전략까지 검증했다고 말하지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/IocpServer.cpp', 'void CIocpServer::Stop()'), ('MultiThreadServer/MultiThreadServer/src/IoBufferPool.cpp', 'void CIoBufferPool::Release(')],
    ('MultiThreadServer/MultiThreadServer/src/IoBufferPool.cpp', 'void CIoBufferPool::Release(', 'p_item->sp_session.reset();', 5))

add(17,
    '로그인을 단순 함수 호출이 아니라 메인 → DB → 메인 순환으로 그렸다. 화살표가 돌아오는 형태는 요청 등록만으로 성공을 응답하지 않고 실제 저장·검증 결과를 회수한다는 의미다.',
    [('Login / Submit', '메인이 로그인 자격·인원·중복 요청 상태를 확인하고 작업 ID와 필요한 값을 DB 작업 큐에 보낸다.'),
     ('DB 쓰레드의 ODBC 연결', '각 DB 쓰레드가 자기 연결을 사용해 인증·계정·유닛·세션 처리를 실행한다. PBKDF2 계산도 DB 작업 경로에 있어 메인에서 기다리지 않는다.'),
     ('TakeResults → UpdateDatabase', '값 결과를 메인이 회수하고 요청 ID·token·현재 연결 상태를 확인한 뒤 stPlayer를 확정하고 응답한다.')],
    '로그인 요청을 받았다고 바로 성공을 보내지 않습니다. 메인이 작업을 큐에 넣고, DB 쓰레드는 자기 ODBC 연결로 비밀번호와 저장 상태를 확인합니다. 결과는 다시 메인으로 돌아옵니다. 그때도 요청한 연결과 token이 현재 유효한지 확인하고 저장된 유닛을 반영한 뒤 성공 응답을 만듭니다. DB가 느린 동안 다른 게임 처리를 계속할 수 있도록 나눈 구조입니다.',
    [('지연 결과를 다시 검증하는 이유', 'DB가 처리하는 동안 사용자가 접속을 끊거나 새 로그인 시도를 할 수 있다. 결과의 작업 ID·세션 소유 token·연결 상태를 확인하지 않으면 오래된 결과가 새 연결이나 이미 끝난 요청에 반영될 수 있다.'),
     ('메모리 상태와 DB 상태', 'databaseBusy는 메인의 중복 요청 제어이고 DB 세션 token·lease는 저장소가 인정하는 소유권이다. 하나가 다른 하나를 완전히 대체하지 않는다. 큐가 찼을 때와 실제 SQL 실패도 별도 경로로 확인한다.')],
    [('DB 쓰레드에서 Player를 바로 수정하면 안 되나요?', '객체 소유권과 게임 순서를 유지하려고 값 결과만 반환했다. 공유 stPlayer를 여러 쓰레드가 수정하면 잠금·수명·순서 문제가 늘어난다.'),
     ('계정 보안을 완성한 서버인가요?', '개인 테스트용 ID·비밀번호 인증과 해시·세션 제어를 구현했다. TLS와 상용 계정 서비스의 전체 보안·운영 요구까지 구현한 것은 아니다.')],
    'DB 큐 등록 성공은 로그인 성공이 아니다. 성공 응답 시점은 실제 DB 결과 확인 이후다.',
    [('MultiThreadServer/MultiThreadServer/src/GamePersistence.cpp', 'void CGameLogic::UpdateDatabase()'), ('MultiThreadServer/MultiThreadServer/src/DatabaseWorker.cpp', 'void CDatabaseWorker::Run()')],
    ('MultiThreadServer/MultiThreadServer/src/DatabaseWorker.cpp', 'vector<stDatabaseResult> CDatabaseWorker::TakeResults()', 'lock_guard lock(m_databaseMutex);', 6))

add(18,
    '이 페이지는 객체도가 아니라 시간 순서가 있는 시퀀스도다. 클라이언트·Game·DB·World를 세로 열로 분리해 서버 이동이 어느 시점의 DB 커밋과 새 연결에 의존하는지 보여준다.',
    [('①~③ 출발 Game 처리', '이동권 요청을 받고 DB 세션을 이동 상태로 반영한다. 결과를 확인한 뒤 이동권을 응답하고 closeAfterSend 등으로 출발 연결을 정리한다.'),
     ('④ 목적지 새 연결', '클라이언트가 이동권의 주소·포트로 World에 새 접속한다. 기존 TCP 소켓이나 메모리 주소를 서버 사이에 넘기는 방식이 아니다.'),
     ('⑤~⑥ 목적지 검증과 입장', 'HMAC 서명·유효 시간·목적지·nonce와 DB 세션을 검증한다. DB 결과 이후 저장된 유닛과 종족별 시작 좌표를 구성한다.')],
    '사용자는 먼저 Game에서 이동권을 요청합니다. Game은 DB에 이동 상태를 저장하고 성공 결과를 받은 뒤 서명된 이동권을 보냅니다. 클라이언트는 World에 새 연결을 열어 이동권을 제출합니다. World는 서명과 만료·nonce·세션 상태를 검사하고 DB 확인을 거쳐 입장을 확정합니다. 이렇게 출발 로그아웃과 목적지 로그인을 명시적으로 나눴습니다.',
    [('서명과 nonce의 다른 역할', '서명은 이동권 내용을 임의로 바꾸지 않았는지 검증한다. nonce와 DB 세션 전이는 같은 이동권을 다시 쓰거나 잘못된 목적지로 들어가는 상황을 통제한다. HMAC은 암호화가 아니므로 내용 비공개를 보장하지 않는다.'),
     ('원래 서버 복귀', '사망·자발적 복귀도 DB에 재입장 가능 시각과 복귀권을 저장·확인하는 경로를 가진다. 원래 Game 서버 정보가 유지되므로 같은 종족의 다른 서버가 있어도 출발 서버로 돌아갈 수 있다.')],
    [('이동 도중 연결이 끊기면?', '즉시 성공 상태로 가정하지 않고 DB token·location·lease·nonce 상태를 기준으로 복구 자격을 확인한다. 현재 구현의 테스트 범위와 완전한 분산 트랜잭션 보장을 구분해야 한다.'),
     ('서버끼리 직접 클라이언트 소켓을 넘기나요?', '아니다. 현재는 클라이언트가 새 TCP 연결을 만들고 서명된 이동권과 DB 세션 상태로 입장한다. SS_Relay는 월드 채팅 중계용 별도 경로다.')],
    '그림의 화살표 높이는 호출 순서를 뜻한다. 가로 거리나 화살표 길이를 실제 네트워크 지연으로 해석하지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/GamePersistence.cpp', 'void CGameLogic::RequestTransfer('), ('MultiThreadServer/MultiThreadServer/src/GamePersistence.cpp', 'void CGameLogic::AcceptTransfer('), ('MultiThreadServer/MultiThreadServer/src/EntryTicket.cpp', 'wire::EntryClaims CEntryTicket::Verify(')],
    ('MultiThreadServer/MultiThreadServer/src/EntryTicket.cpp', 'wire::EntryClaims CEntryTicket::Verify(', 'const string signature = Sign(', 7))

add(19,
    '명령 처리와 일정 주기의 시간 진행을 한 루프에 배치해, Update 호출 횟수와 전장 Tick 횟수가 다름을 설명한다. 네 상자는 메인에서 반복하는 순서이며 네 쓰레드가 아니다.',
    [('외부 결과 회수 → 명령 실행', 'DB·Redis·중계 결과를 가져오고 명령 큐에서 이번 처리 예산만 꺼낸다. 새 명령이 없어도 외부 결과·연결 정리·틱 시간 확인은 필요하다.'),
     ('연결 정리 → Tick 시각 확인', '연결 종료 상태를 정리한 뒤 실제 시간이 다음 틱 시각에 도달했는지 본다. sleep_for(1ms)가 TickRate를 정하는 것은 아니다.'),
     ('Tick 내부 순서', '스킬 → 이동 → 승패 → 기록 → 상태 전송 순서를 메인이 결정한다. 여러 독립 계산은 전투 쓰레드에 맡겨도 이 큰 실행 순서는 유지한다.')],
    '메인은 Update를 반복하지만 매번 전투를 한 번씩 계산하지는 않습니다. TickRate=20이면 목표 간격은 50ms이고 다음 틱 시각에 도달했을 때 Tick을 실행합니다. 그 사이에는 DB 결과나 입력 명령을 처리할 수 있습니다. 지연되면 최대 다섯 틱을 따라가고 계속 밀리면 생략 틱을 집계합니다. 따라서 입력이 없다고 게임 시간 전체가 멈추는 구조도 아닙니다.',
    [('세 주기 구분', '메인 루프 반복, 전투 20Hz, Snapshot 약 5Hz는 다른 주기다. 원본 기록은 FrameTicks=1로 전투 틱마다 저장하지만 1,500명 시연은 FrameTicks=4를 사용했다. 화면 전송과 기록 주기를 바꾼 것이 전투 계산 빈도를 바꾼 것은 아니다.'),
     ('기다림이 미치는 영향', 'Tick에서 Run이 반환되기 전에는 메인이 다음 명령을 꺼내지 못한다. 병렬화가 이 대기 시간을 줄일 수 있지만 직렬 판정과 동기화 비용은 남는다. MP 초당 회복은 실제 벽시계에 독립적인 별도 타이머가 아니라 현재 틱 수 기준 계산이다.')],
    [('TickRate=1로 바꾸면?', '목표 전장 틱 간격이 1초가 된다. 이동·피해·회복의 시간 해상도가 달라지며 단순히 네트워크 쓰레드 수를 바꾸는 설정은 아니다.'),
     ('정확히 50ms마다 실행되나요?', '목표 주기다. OS 스케줄링·작업 시간에 따라 실제 시작 시각은 늦어질 수 있어 처리 시간과 생략 틱을 계측한다.')],
    '20Hz는 프레임이 반드시 안정적으로 20회 완료됨을 보증하는 숫자가 아니다. 설정 목표와 실행 관측치를 구분한다.',
    [('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::Update()'), ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::Tick()'), ('Server.ini', 'TickRate=20')],
    ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'void CGameLogic::Update()', 'const auto interval', 9))

add(20,
    '코드를 입력·계산·반영 세 구간으로 나눠 보여줘, 단순히 for문을 여러 쓰레드에서 돌렸다는 설명을 넘어서 동시 쓰기 충돌을 피한 근거를 제시한다.',
    [('미리 만든 inputs/results', '이동 입력은 메인이 값으로 준비하고 결과 배열도 크기를 확정한다. 계산 중 vector를 확장하지 않아 각 결과 슬롯의 위치를 유지한다.'),
     ('m_battleWorkers.Run 콜백', '항목 i의 계산은 inputs[i]와 읽기 전용 맵·건물을 사용해 results[i]에만 쓴다. 실제 player의 좌표를 여기서 바꾸지 않는다.'),
     ('Run 이후 set_x/set_y', '모든 전투 쓰레드가 끝난 뒤 메인이 결과를 유닛에 반영한다. 기본 공격·사망·킬·승패 같은 의존적인 판정은 메인에 남아 있다.')],
    '이동은 메인이 입력을 만들고 전투 쓰레드들이 결과 배열의 다른 칸을 채우게 했습니다. Run은 계산이 모두 끝나야 반환합니다. 그래서 그 다음의 set_x와 set_y는 완성된 결과를 메인이 반영하는 구간입니다. 계산 중 입력과 건물을 바꾸지 않고 결과 칸도 겹치지 않으므로 유닛별 상태 잠금을 계속 잡지 않아도 됩니다.',
    [('같은 패턴을 쓴 스톰', 'UpdateSkills는 한 스톰 범위의 모든 대상 목록을 만들고 대상별 남을 HP·실드를 계산한다. 피해 적용·죽음·복귀는 완료 후 메인이 수행한다. 200명이 범위에 있으면 조건을 검사할 대상도 200명이며 설명 예시의 100명은 제한이 아니다. 겹치는 여러 스톰은 앞 결과 반영 뒤 처리한다.'),
     ('같은 패턴을 쓴 Snapshot', 'BroadcastWorldState에서는 유닛 하나가 아니라 수신자 한 명이 계산 단위다. 대상별 시야 선택과 Protobuf 직렬화를 전투 쓰레드에서 만들고, 메인은 완성 바이트를 해당 연결의 SendPacket에 넘긴다. 이것은 OS 송신 작업을 전투 쓰레드가 수행한다는 뜻은 아니다.')],
    [('왜 results에 쓸 때 뮤텍스가 없나요?', '메인이 결과 공간을 먼저 확보하고 각 i는 한 전투 쓰레드가 담당하며 메인은 완료 전 결과를 읽지 않는다. 계산 중 컨테이너 크기·입력을 변경하지 않는 전제가 있다.'),
     ('모든 전투가 병렬인가요?', '아니다. 이동·MP, 같은 스톰의 대상별 피해, 수신자별 시야·직렬화 같은 독립 계산만 나눈다. 여러 유닛이 같은 적의 HP를 동시에 직접 갱신하게 하지 않았다.')],
    '람다의 [&]가 자동으로 쓰레드 안전성을 주지 않는다. Run의 완료 대기와 읽기·쓰기 범위가 수명·경쟁 안전성의 근거다.',
    [('MultiThreadServer/MultiThreadServer/src/GameBattle.cpp', 'void CGameLogic::MovePlayers()'), ('MultiThreadServer/MultiThreadServer/src/GameSkills.cpp', 'void CGameLogic::UpdateSkills()'), ('MultiThreadServer/MultiThreadServer/src/GameSnapshot.cpp', 'void CGameLogic::BroadcastWorldState()')],
    ('MultiThreadServer/MultiThreadServer/src/GameBattle.cpp', 'void CGameLogic::MovePlayers()', 'm_battleWorkers.Run(inputs.size(),', 6))

add(21,
    '작업을 게시하는 Run과 실제 쓰레드 진입점 Work를 좌우로 놓아 역할을 구분했다. 완료 개수·세대 번호·조건변수의 관계를 설명할 수 있어야 병렬 for문의 실행 원리를 이해한 것이다.',
    [('Run의 작업 게시', 'm_battleMutex 아래에서 계산 함수·항목 수·남은 쓰레드 수를 설정하고 세대 번호를 늘린다. notify_all은 새 작업을 확인하도록 대기 쓰레드를 깨운다.'),
     ('Work의 인덱스 분할', '4개면 0/4/8…, 1/5/9…, 2/6/10…, 3/7/11…로 분담한다. 유닛이 1,500개여도 각 쓰레드는 자기 항목을 반복 계산할 수 있다.'),
     ('m_remaining과 m_done', '모든 쓰레드가 자기 몫을 끝내야 메인이 깨어나 Run이 반환한다. 조건변수 대기 중에는 mutex를 놓고 깨어난 뒤 다시 얻는다.')],
    'Run은 새 쓰레드를 만드는 함수가 아니라 이미 만든 전투 쓰레드들에 이번 계산을 게시하는 함수입니다. Work는 평소 조건변수에서 쉬다가 세대가 바뀌면 자기 인덱스들을 계산합니다. 먼저 끝난 쓰레드는 남은 개수를 줄이고 다음 작업을 기다립니다. 마지막 쓰레드가 완료를 알리면 메인이 다음 상태 반영을 시작합니다.',
    [('큐 누적형과의 차이', '현재 메인만 Run을 호출하고 그 호출에서 기다리므로 전투 계산 묶음이 별도 큐에 무한히 쌓이지 않는다. 계산 중 새 클라이언트 입력은 별도 m_commands에 쌓일 수 있다. 유휴 쓰레드 하나를 골라 작업 하나씩 보내는 동적 스케줄러도 아니다.'),
     ('예외와 단일 계산 모드', '한 쓰레드가 예외를 내도 완료 집계에 참여하고, 메인이 저장한 예외를 다시 던진다. WorkerCount=1이면 별도 전투 쓰레드를 만들지 않고 같은 콜백을 호출한 메인이 직접 반복한다. 서버 전체가 싱글쓰레드라는 의미는 아니다.')],
    [('for(;;)이면 CPU를 계속 사용하나요?', '루프 안의 wait에서 새 세대 또는 종료 조건을 기다린다. 바쁜 반복과 달리 조건변수가 쉬는 구간을 제공한다.'),
     ('모두 일하는데 다음 작업은 어디에 쌓이나요?', '현재는 메인이 이전 Run의 완료를 기다리므로 다음 전투 묶음을 게시하지 않는다. 클라이언트 입력 큐와 전투 계산 배열을 구분해야 한다.')],
    '이 클래스는 현재 단일 메인 호출을 전제로 사용한다. 여러 호출자가 동시에 서로 다른 Run을 게시해도 되는 범용 작업 큐라고 설명하지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/BattleWorkers.cpp', 'void CBattleWorkers::Run('), ('MultiThreadServer/MultiThreadServer/src/BattleWorkers.cpp', 'void CBattleWorkers::Work(')],
    ('MultiThreadServer/MultiThreadServer/src/BattleWorkers.cpp', 'void CBattleWorkers::Work(', 'for (size_t i = index;', 5))

add(22,
    '대규모 인원에서 전투 상태 전체를 모든 사람에게 보내는 비용을 줄이는 과정을 네 상자로 나눴다. 공간 검색·게임 시야 규칙·직렬화·송신 등록을 따로 읽어 각 단계의 역할과 한계를 설명한다.',
    [('공간 인덱스', '현재 좌표로 검색 인덱스를 만든다. Grid는 가까운 셀의 후보를 찾는 방법이고 Linear는 전체 좌표를 확인하는 비교 경로다.'),
     ('수신자별 선택', '주변 후보에서 CanSee로 은신·탐지 등을 검사하고 거리순으로 적 32명·아군 31명과 자신을 선택한다. SnapshotRadius>0인 근처 전송 모드의 제한이다.'),
     ('조각과 complete', '선택한 유닛은 메시지당 4개씩 담는다. 마지막 조각의 complete 표시와 같은 tick을 이용해 클라이언트가 상태 묶음을 완성한다.')],
    '먼저 위치 인덱스로 근처 후보를 줄이고, 실제로 보낼 대상은 공통 시야 규칙으로 결정합니다. 그 다음 수신자마다 상태 메시지를 만들어 Protobuf로 직렬화합니다. 유닛을 네 개씩 나눠 담고 마지막 조각을 표시해 클라이언트가 같은 틱의 상태를 조립합니다. 이 과정은 표시와 전송 범위를 줄이는 것이며 서버의 실제 참가자나 스톰 대상 수를 줄이는 것은 아닙니다.',
    [('같은 규칙으로 결과 비교', 'Linear와 Grid는 후보를 찾는 방법만 다르고 SelectSnapshotPlayers의 은신·거리순 제한은 공유한다. VerifySpatialSearch=1이면 선택 결과를 대조한다. 거리 동점은 player ID로 순서를 고정해 결과가 셀 순회 순서에 흔들리지 않게 한다.'),
     ('밀집과 남은 비용', '모든 유닛이 같은 셀에 모이면 Grid도 후보를 많이 확인한다. CanSee 안의 탐지 수단 검색에는 선형 순회가 남는다. SnapshotRadius=0은 전체 시야 경로이므로 항상 64명 제한이라고 말하지 않는다.')],
    [('전장에 200명이 모이면 스톰도 64명만 맞나요?', '아니다. Snapshot 선택은 수신자에게 보낼 목록이고 전투 범위 검색은 별도다. 스톰은 범위 안에서 적용 조건을 만족하는 전체 대상을 계산한다.'),
     ('함수 이름이 Broadcast인데 모두 같은 내용을 받나요?', '아니다. 각 수신자의 좌표·시야를 기준으로 목록이 달라진다. 동일한 전장 틱을 각자에게 맞는 패킷 묶음으로 만든다.')],
    '원본 하단의 GameSnapshot.cpp::Snapshot은 설명용 약칭이다. 실제로 찾을 함수는 CGameLogic::BroadcastWorldState다.',
    [('MultiThreadServer/MultiThreadServer/src/GameSnapshot.cpp', 'void CGameLogic::BroadcastWorldState()'), ('MultiThreadServer/MultiThreadServer/src/GameLogic.cpp', 'CGameLogic::SelectSnapshotPlayers('), ('MultiThreadServer/MultiThreadServer/src/SpatialIndex.cpp', 'CSpatialIndex::QueryGrid(')],
    ('MultiThreadServer/MultiThreadServer/src/GameSnapshot.cpp', 'void CGameLogic::BroadcastWorldState()', 'm_battleWorkers.Run(results.size(),', 6))

add(23,
    'Acquire·작업·완료·재사용을 순환 가능한 네 단계로 표현했다. 단순 new/delete 최적화보다 OS가 버퍼를 사용하는 기간에 재사용하지 않는 규칙이 더 중요함을 보여준다.',
    [('Acquire와 m_free', '반환된 객체가 있으면 꺼내고 없으면 상한 안에서 새로 만든다. PoolCapacity만큼 시작부터 모두 할당하는 구조는 아니다.'),
     ('stIoOperation', 'OVERLAPPED·작업 종류·세션 참조·Accept용 소켓·4096바이트 배열·길이를 함께 보관한다. Player나 모든 Protobuf 객체를 풀링하지 않는다.'),
     ('완료 후 Release', '완료를 회수했거나 요청 등록 자체가 실패한 경우만 반환한다. 세션 참조·자원을 정리하고 사용 통계를 갱신한 뒤 free list에 넣거나 삭제한다.')],
    '풀의 단위는 고정 크기 I/O 작업 객체입니다. 등록부터 완료까지 버퍼 주소가 유지돼야 하므로 이 객체를 재사용합니다. 풀이 켜져 있으면 반환 목록을 사용하고, 꺼져 있어도 같은 Acquire·Release 위치에서 new/delete해 비교할 수 있게 했습니다. 고갈되면 현재 연결을 정리하고 Accept는 여유가 생길 때 보충합니다.',
    [('지표의 의미', '4168바이트는 해당 x64 빌드에서 확인한 I/O 객체 크기다. 79,096→205는 비교 실행의 World I/O 신규 생성 수 중앙값이지 모든 힙 할당이 그만큼 줄었다는 뜻은 아니다. 8192개 상한이 곧 항상 그 크기의 실제 메모리를 선할당한다는 뜻도 아니다.'),
     ('잠금과 성능의 선택', 'm_poolMutex는 반환 목록과 통계 접근을 보호한다. 이 풀은 락 프리 자료구조가 아니다. 재사용은 할당 호출을 줄이지만 메모리를 보유하고 잠금 비용이 있으므로 RTT·CPU·메모리도 같이 봐야 한다.')],
    [('왜 전송 등록 직후 반환하지 않나요?', 'Windows가 아직 그 버퍼를 사용할 수 있기 때문이다. 완료 통지를 회수하기 전에 다른 작업이 같은 메모리를 쓰면 데이터가 덮일 수 있다.'),
     ('풀을 끄면 코드 흐름도 달라지나요?', 'I/O 요청과 완료 경로는 같고 객체 할당·반환 방식이 달라진다. 같은 기능에서 풀의 영향을 비교하기 위한 설정이다.')],
    '일반적인 모든 메모리 할당 제거, 락 프리 풀, 풀 덕분의 RTT 개선을 구현·입증했다고 확대하지 않는다.',
    [('MultiThreadServer/MultiThreadServer/src/IoBufferPool.cpp', 'stIoOperation* CIoBufferPool::Acquire('), ('MultiThreadServer/MultiThreadServer/src/IoBufferPool.cpp', 'void CIoBufferPool::Release(')],
    ('MultiThreadServer/MultiThreadServer/src/IoBufferPool.cpp', 'stIoOperation* CIoBufferPool::Acquire(', 'if (m_enabled && !m_free.empty())', 6))

add(24,
    '점수 확정·실시간 조회·최종 저장을 별도 경로로 그려, Redis를 점수 원본이나 계정 DB 전체의 대체물로 오해하지 않게 한다. 각 선이 비동기 경계를 통과한다는 점도 보여준다.',
    [('메인의 m_ranking', '입장·사망·킬은 서버가 확정하고 경기 ID 안의 누적 총계로 보관한다. 클라이언트가 자기 킬 수를 올려 보내는 구조가 아니다.'),
     ('Redis 게시와 조회', 'Sorted Set의 kills/deaths/entries와 플레이어 정보에 총계를 반영한다. 조회는 상위 10명과 본인 순위를 요청하고 결과 ID로 메인 연결과 다시 매칭한다.'),
     ('경기 종료 결과', '최종 총계를 XML과 MSSQL에 저장·재적재할 수 있게 한다. 조회 Redis가 장애여도 전투 총계 생성과 경기 진행의 책임은 메인에 남는다.')],
    '점수는 World 메인이 게임 결과를 바탕으로 만듭니다. 최신 총계를 Redis 쓰레드에 넘기면 경기별 Sorted Set에 반영하고, 클라이언트의 순위 요청은 비동기로 조회해 메인이 응답합니다. 순위 조회용 저장소와 최종 결과 저장은 분리했습니다. Redis 재연결 때 현재 총계를 다시 게시하므로 실패 응답 뒤 같은 점수를 중복 가산하지 않도록 총계 덮어쓰기를 사용했습니다.',
    [('재시도와 최신 값', 'ZINCRBY로 사건마다 무조건 더하는 대신 ZADD 총계를 게시한다. 응답 유실 후 재시도해도 동일 총계 덮어쓰기가 가능하다. Publish는 최신 불변 복사본으로 합쳐 장애 동안 모든 중간 총계를 무한 큐에 보관하지 않는다.'),
     ('지속성과 복구 범위', 'Redis 재시작 후 실행 중인 World의 총계를 재게시하는 것과 World 프로세스 자체의 전투 상태 복구는 다르다. 현재 World 진행 상태 전체의 장애 복원은 구현 범위가 아니다. final SQL도 경기 종료 결과 보존 경로이며 실시간 전투 상태 복원의 대체물이 아니다.')],
    [('킬은 어디서 세나요?', '메인의 CountDeath가 피해자 상태와 killer ID·진영을 확인해 집계한다. 스톰 시전자가 먼저 복귀해도 시전 시 보관한 식별 정보를 사용한다.'),
     ('왜 순위 조회 전에 Publish하나요?', '입장 직후 자신의 0킬·진입 1회 등 최신 총계가 반영되도록 한다. 그래도 외부 I/O와 오류가 있으므로 성공 여부는 실제 조회 결과로 응답한다.')],
    '아군 피해·자발적 back·사망을 같은 사건으로 집계하지 않는다. Redis로 조회한다는 것과 MSSQL에 결과를 남기지 않는다는 것은 다른 주장이다.',
    [('MultiThreadServer/MultiThreadServer/src/GameRanking.cpp', 'void CGameLogic::CountDeath('), ('MultiThreadServer/MultiThreadServer/src/RedisWorker.cpp', 'void Save('), ('MultiThreadServer/MultiThreadServer/src/GameRanking.cpp', 'void CGameLogic::FinishMatch(')],
    ('MultiThreadServer/MultiThreadServer/src/RedisWorker.cpp', 'void Save(', 'Append(p_connection, {"ZADD", key + ":kills"', 4))

add(25,
    '전투 상태가 기록 파일이 되는 파이프라인을 그렸다. 기록할 내용과 디스크 쓰기를 분리하고, 정상 완성 파일과 실패한 부분 파일을 구분하는 이유를 설명한다.',
    [('CaptureReplay와 Capture', '메인이 전체 전장 상태·허용된 행동 정보를 구성한다. 수신자별 근처 Snapshot과 달리 기록에는 전체 전장 복원에 필요한 상태를 사용한다.'),
     ('full과 delta', '첫 프레임·주기 스냅샷에는 전체 상태, 그 사이에는 변경 유닛과 제거 ID 등을 저장한다. 나중에 가까운 full부터 복원할 수 있게 한다.'),
     ('제한 큐 → 파일 쓰레드', '직렬화된 레코드를 길이·체크섬과 함께 큐로 보내고 기록 쓰레드가 순서대로 쓴다. Footer를 정상 기록한 뒤 완성 확장자로 정리한다.')],
    '리플레이는 로그인 패킷을 그대로 덤프한 로그가 아니라 전투 복원용 기록입니다. 메인이 허용된 행동과 상태를 구성하고 CRecorder가 전체·변경 프레임을 직렬화합니다. 디스크 쓰기는 전용 쓰레드가 수행합니다. 큐·파일 상한이나 쓰기 실패가 나면 기록을 실패로 표시해 부분 파일을 정상 완성 파일로 취급하지 않습니다.',
    [('무엇이 저장되지 않는가', '비밀번호·세션 token·이동권 원문 같은 인증 정보를 전투 행동 기록에 복사하지 않는다. Game.proto의 Replay 레코드와 GameReplay의 명령 화이트리스트를 확인한다. 게임 상태 구성·직렬화 비용은 여전히 호출 경로에 있고 모든 기록 작업이 쓰기 쓰레드로 이동한 것은 아니다.'),
     ('complete의 두 의미', 'Replay Footer의 정상 완성은 파일이 끝까지 기록됐다는 뜻이고, SQL 경기 complete·winner는 승패 종료와 관계된 상태다. 시간 제한 서버 종료도 파일은 정상 완성될 수 있다. 1,500명 시연에서 이 둘을 섞지 않는다.')],
    [('명령만 기록하고 다시 시뮬레이션하나요?', '현재는 상태 full/delta와 행동을 기록해 상태를 복원한다. 같은 입력만으로 전체 전투를 다시 계산하는 결정론적 재시뮬레이션 방식은 아니다.'),
     ('디스크가 느리면 전투가 멈추나요?', '전용 쓰기 쓰레드와 제한 큐로 직접적인 디스크 대기를 분리했다. 상한 초과에서는 기록을 실패 처리한다. 직렬화·큐 잠금 등 모든 간접 비용까지 사라지는 것은 아니다.')],
    '리플레이 레코드 길이·체크섬 형식과 TCP의 4바이트 공통 헤더는 별개의 파일·통신 형식이다.',
    [('MultiThreadServer/MultiThreadServer/src/GameReplay.cpp', 'void CGameLogic::CaptureReplay('), ('MultiThreadServer/MultiThreadServer/src/Replay.cpp', 'void CRecorder::Capture('), ('MultiThreadServer/MultiThreadServer/src/Replay.cpp', 'bool CRecorder::Enqueue(')])

add(26,
    '시간선을 full 하나와 delta 여러 개로 그려, 특정 시각으로 이동할 때 모든 기록을 처음부터 적용할 필요가 없다는 원리를 설명한다. 재생 시각과 저장 인덱스의 역할을 분리한다.',
    [('Target → 앞 full 찾기', 'FindTime은 목표 시간 이하 프레임 인덱스를 찾는다. StateAt은 그 인덱스 이전의 가장 가까운 전체 스냅샷을 기준점으로 삼는다.'),
     ('delta 순서 적용', 'full 이후 변경 프레임을 차례로 Apply한다. 바뀐 유닛을 갱신하고 removed ID를 지워 해당 시각의 전체 상태를 만든다.'),
     ('배속 시계', '실제 경과시간에 speed를 곱해 기록상의 재생 시각을 전진시킨다. 배속은 기록을 빨리 표시하는 것이지 서버 틱 설정을 다시 바꾸는 기능이 아니다.')],
    '120초로 이동하면 먼저 해당 시각의 프레임을 고르고, 바로 앞 full 스냅샷부터 변경분을 적용합니다. 예를 들어 119초가 기준 스냅샷이면 그 이후 delta를 순서대로 적용해 120초 상태를 복원합니다. 120초 자체가 full이면 그 프레임부터 시작합니다. 뷰어는 복원된 결과를 그리며 당시 전투 규칙을 다시 실행해 승패를 계산하지 않습니다.',
    [('파일 인덱스와 적용 비용', '로딩 시 frames와 전체 스냅샷 위치 목록을 만들고 StateAt이 그 목록을 이용한다. 현재 StateAt의 스냅샷 탐색은 목록 순회이고 FindTime은 upper_bound를 사용한다. 모든 접근이 O(1)이라고 설명하지 않는다.'),
     ('상태 저장 재생의 장단점', '서버 코드 버그를 같은 입력으로 재현하는 시뮬레이션 도구와 목적이 다르다. 당시 서버가 확정한 결과를 보기에는 유용하지만 저장 빈도 사이의 세부 상태와 누락된 판정 근거까지 임의로 복원하지는 못한다.')],
    [('seek하면 서버에 다시 접속하나요?', '아니다. 현재는 로컬 기록을 로드해 오프라인으로 상태를 복원한다.'),
     ('실제 시간 1초와 저장 시간 1초가 항상 같은가요?', '기록 시간은 틱과 tickRate를 기준으로 구성된다. 실행 중 지연·생략 틱과 실제 벽시계 진행은 별도로 보아야 한다. 배속은 이 기록 시간에 적용한다.')],
    '원본의 119.0→120.0은 복원 순서 설명용 예시다. 모든 기록에서 정확히 그 인덱스 배열이 나온다는 뜻은 아니다.',
    [('MultiThreadServer/MultiThreadServer/src/Replay.cpp', 'stArchive::StateAt('), ('MultiThreadServer/MultiThreadServer/src/Replay.cpp', 'stArchive::FindTime('), ('DummyClient/src/ReplayWindow.cpp', 'void CReplayWindow::Seek(')],
    ('MultiThreadServer/MultiThreadServer/src/Replay.cpp', 'stArchive::StateAt(', 'size_t first = 0;', 9))

add(27,
    '실제 복원 화면을 가운데 크게 두고 관찰할 위치를 세 묶음으로 정리했다. 텍스트 로그에서 확인하기 어려운 좌표 변화·건물 HP·사망과 재입장을 시각적으로 설명하는 장이다.',
    [('전장 지도', '원점과 맵 범위, 진영 시작점, 유닛·건물·스킬 영역을 보인다. 좌표는 서버 상태를 화면 좌표로 변환해 그린다.'),
     ('오른쪽 상태 패널', '진영별 인원·건물 상태·선택 유닛의 HP/MP·좌표를 함께 확인한다. 단순 이미지 애니메이션만 보여주는 화면이 아니다.'),
     ('재생 조작과 묶음 표시', '재생/정지·배속·탐색으로 같은 순간을 재확인한다. 전체가 100명 초과면 일부 겹친 표시는 ×인원으로 묶지만 실제 상태 항목은 유지한다.')],
    '이 화면은 실제 전투 기록의 한 시점을 복원한 것입니다. 전체 움직임을 먼저 보여준 뒤 한 유닛을 선택해 좌표와 HP 변화를 확인하겠습니다. 많은 유닛이 겹칠 때는 표시를 묶지만 오른쪽 참가 수와 원본 상태는 유지됩니다. 과거 시점으로 돌아가 같은 사건을 반복 확인할 수 있어 테스트 결과를 설명하는 도구로 사용했습니다.',
    [('표시 집계와 전투 판정', '×20 표시는 20개 유닛을 클라이언트 화면에서 묶어 그린 것이다. 서버에 대표 유닛 하나만 남긴 것이 아니며 스톰 대상을 100명으로 자르거나 전송 Snapshot 64명으로 전장을 축소한 것도 아니다.'),
     ('시연 때 짚을 장면', '건물 HP 감소, 유닛 HP 0과 Return, 같은 계정의 재진입, 스톰 영역, seek 전후 일치 같은 관찰점을 미리 선택한다. 화면이 자연스럽다는 인상만으로 DB 저장이나 서버 처리량을 증명했다고 말하지 않는다.')],
    [('유닛 이미지가 서버에서 내려오나요?', '현재 뷰어가 로컬 이미지 자산을 사용하고 서버 상태의 유닛 종류를 그림에 대응시킨다. 서버는 상태 데이터를 기록한다.'),
     ('모든 입력·충돌이 원작과 같나요?', '원작 지상 유닛·전투 스킬을 참고했지만 단순화된 개인 프로젝트다. 유닛 간 충돌·경로 탐색·상용 클라이언트 완성도까지 구현하지 않았다.')],
    '이미지 자산의 권리와 개인 검증용 사용 범위를 유지한다. 화면을 직접 제작한 원작 자산이라고 설명하지 않는다.',
    [('DummyClient/src/ReplayWindow.cpp', 'void CReplayWindow::'), ('DummyClient/src/ReplayWindow.cpp', 'if (m_state.units_size() <= 100)')],
    ('DummyClient/src/ReplayWindow.cpp', 'void CReplayWindow::', 'if (m_state.units_size() <= 100)', 5))

add(28,
    '세 시점의 썸네일을 시간 순서로 놓아 시연 영상의 편집 동선을 제안했다. 실제 올라간 영상을 증명하는 페이지가 아니라 어떤 기능을 보여줄지 정리한 녹화 구성안이다.',
    [('45초 → 75초 → 210초', '준비·집결, 교전, 후반 상태로 이어지는 기록상의 세 시점이다. 세 썸네일만으로 모든 검증이 완료됐다는 뜻은 아니다.'),
     ('영상의 관찰 순서', '전체 전장 → 개별 유닛 상태 → 사망/재입장 → 배속 → seek 순서로 기능이 실제 조작되는 모습을 보여줄 수 있다.'),
     ('향후 링크 연결', '영상 URL이 정해지면 썸네일 클릭 링크와 QR을 붙일 수 있다는 계획이다. 현재 원본에는 업로드된 영상 링크가 없다.')],
    '이 장은 영상이 이미 게시됐다는 설명이 아니라 녹화 구성안입니다. 실제 기록의 집결·교전·후반 화면을 사용했습니다. 영상을 만든다면 전체 화면으로 시작해 유닛 상태와 사망·재입장을 보여주고, 재생 정지·배속·seek를 직접 조작하겠습니다. 검증 수치는 영상 인상과 별도로 뒤의 표와 로그로 설명하겠습니다.',
    [('촬영 전 준비', '원본 파일과 재생 프로그램을 고정하고 재생할 시점을 적는다. 계정 비밀번호·운영 주소·토큰이 화면에 노출되지 않는지 확인하고, 원본 속도와 배속 장면을 구분한다. 실제 업로드는 별도 사용자 요청과 URL 확인 후 진행한다.'),
     ('현재 설명의 한계', '영상 페이지의 존재는 유튜브 업로드·외부 공개·링크 유효성을 의미하지 않는다. 녹화 전에는 장면 구성안이라고 말하고, 업로드 뒤 실제 URL과 PDF 링크를 시험해 제출본을 갱신한다.')],
    [('지금 PDF에서 클릭하면 영상이 나오나요?', '현재는 구성안과 실제 정지 화면이다. 외부 URL이 연결됐다고 말하지 않는다.'),
     ('영상이 있으면 성능 표는 없어도 되나요?', '아니다. 영상은 동작 이해를 돕고 성능 표는 재현 조건·원본 지표와 수치를 설명한다. 서로 다른 근거다.')],
    '실행하지 않은 녹화·업로드를 완료한 것처럼 말하지 않는다. 이 해설 제작에서도 외부 게시를 수행하지 않는다.',
    [('DummyClient/src/ReplayWindow.cpp', 'void CReplayWindow::Seek('), ('docs/results/2026-10-19/iocp/stress-validation.json', None)])

add(29,
    'A~E는 디자인 테마가 아니라 서로 다른 실행 설정에 붙인 실험 조건 이름이다. 표에서 공통 조건과 바꾸는 조건을 분리해 인과관계를 과하게 해석하지 않게 한다.',
    [('A → B', 'WSAPoll에서 IOCP로 네트워크 경로를 바꾸며 전투 계산은 메인 모드 1로 유지한다. 두 경로는 준비 상태 확인과 완료 통지 처리 방식이 다르다.'),
     ('B → C', 'IOCP를 유지하고 I/O 객체 풀만 OFF→ON으로 바꾼다. 같은 Acquire/Release 위치에서 재사용의 비용을 비교한다.'),
     ('C → D → E', '네트워크·풀을 유지하고 전투 쓰레드 설정 1→2→4만 바꾼다. 검증 옵션은 별도 시험에서 사용하고 성능 측정에서는 끈다.')],
    '비교는 다섯 설정으로 나눴습니다. 먼저 Poll과 IOCP 경로를 비교하고, 그다음 IOCP 안에서 풀을 켠 효과를 봅니다. 마지막으로 같은 IOCP·풀 설정에서 전투 계산을 1·2·4로 나눕니다. 네트워크와 DB 쓰레드는 이 표의 비교 동안 각각 2개로 고정했습니다. 표의 A~E는 실험 조건 식별자입니다.',
    [('공통 게임 로직의 의미', 'HandlePacket·Tick·독립 계산 함수 등 게임 규칙은 공통이고 네트워크 방식과 계산 실행 설정이 달라진다. 워커 1은 별도 전투 쓰레드 하나가 아니라 메인이 동일 함수를 직접 실행하는 모드다.'),
     ('현재값과 시험 사본', '원본 Server.ini는 현재 기본 실행값이다. 과거 각 시험에는 실행 폴더의 설정 사본이 있다. 나중에 기본값이 바뀌어도 과거 측정 조건을 원본 기본값으로 덮어 설명하지 않는다.')],
    [('네트워크/DB 1/1→2/2→4/6 비교와 같은 건가요?', '다른 시험 축이다. 이 장은 네트워크·풀·전투 계산 조합 다섯 조건이고 Network/DB는 2/2로 고정했다. 이전 워커 비교 이력과 별개로 설명한다.'),
     ('설정만 바꾸면 즉시 적용되나요?', '서버 시작 때 읽는 값이므로 재시작해야 한다. 실행 파일·설정 사본·CSV와 부하 스크립트를 함께 보관해 비교 조건을 고정한다.')],
    '이 표의 A~E를 문서 디자인 테마 표기로 혼동하지 않는다. 검증 모드를 켠 채 나온 지연을 성능 표와 혼합하지 않는다.',
    [('Server.ini', '[Network]'), ('Server.ini', '[Memory]'), ('Server.ini', '[Battle]'), ('docs/results/2026-10-19/iocp/matrix/plan.json', None)])

add(30,
    '정상 기능·계산 동등성·실패·자원 회수를 서로 다른 시험 축으로 나눴다. 성능 막대그래프를 보기 전에 잘못된 입력과 종료에서도 설계가 유지되는지를 확인했다는 순서다.',
    [('기능 회귀와 계산 동등성', '게임 흐름을 재현하고 고정 입력 1,500개×200회에 대해 계산 결과를 비교한다. 워커 수가 달라도 값·패킷이 같아야 한다.'),
     ('프레임·RST·느린 수신', '부분 헤더·병합 패킷, 반복 접속, 비정상 연결 종료, 읽지 않는 수신자 같은 정상 밖 경로를 시험한다.'),
     ('풀 고갈과 종료 지표', 'PoolCapacity를 작게 해서 실패 경로를 실제로 만들고 Accept 보충과 반환을 확인한다. 잔여 I/O와 사용 중 블록을 종료 시 점검한다.')],
    '성능을 보기 전에 정상 동작과 실패 경로를 분리해서 확인했습니다. 직렬·병렬 결과가 같은지 비교하고, 부분 패킷·재접속·RST·느린 수신과 풀 고갈을 시험했습니다. 종료 시 잔여 I/O와 사용 중 블록이 없는지도 확인했습니다. 이 결과는 해당 시험 경로의 검증이며 장시간 무중단 운영을 보장하는 자료는 아닙니다.',
    [('회귀 시험과 부하 시험', '회귀 시험은 정답·오류 거부·복구 순서를 확인한다. 부하 시험은 동일 조건에서 지연·CPU·메모리 등을 측정한다. 회귀가 통과했다는 이유로 처리량 개선률을 새로 계산하지 않는다.'),
     ('날짜별 근거', '원본 표는 10/19 IOCP 구현 당시의 시험 기록을 제시한다. 10/20~21 가독성·이름 수정 뒤에는 별도의 기능 회귀를 수행했다. 코드 이름 변경 뒤 과거 부하 수치를 같은 날 새로 측정했다고 말하지 않는다.')],
    [('병렬 결과가 같다는 것은 어떻게 확인했나요?', '고정된 입력으로 같은 계산 함수를 직렬로도 실행해 위치·MP·HP·실드 또는 패킷 바이트를 비교한다. 예외 뒤 다음 작업 재사용도 시험한다.'),
     ('pending_io=0이면 누수가 전부 없나요?', '그 지표는 진행 중 I/O 회수와 풀 사용 블록의 종료 상태다. 모든 메모리·외부 핸들·장시간 누수를 검증한 지표로 확대하지 않는다.')],
    '실패 로그에 FAIL이라는 단어가 있어도 시험이 의도한 손상·거부 검증일 수 있다. 최종 종료 코드와 기대 결과를 함께 읽는다.',
    [('test-iocp.ps1', None), ('test-parallel.ps1', None), ('docs/results/2026-10-21/mutex-roles/regression.json', None), ('MultiThreadServer/MultiThreadServer/src/BattleCalculation.cpp', 'int RunBattleChecks()')])

add(31,
    '조건 수·참가자 수·시간을 큰 숫자로 먼저 보여주고 아래에 고정한 환경을 적었다. 수치 그래프가 어떤 부하와 실행 방식에서 나온 것인지 판단할 수 있게 하는 실험 설명 장이다.',
    [('5×3과 96명', '다섯 설정을 각각 세 번 실행한 총 15회 비교다. 최대 수용량을 찾기 위한 1,500명 시연과 다른 시험이다.'),
     ('3초 워밍업 + 12초 측정', '시작 직후 준비 구간과 지표 집계 구간을 구분한다. 짧은 반복 측정이며 장시간 누적 부하를 검증한 자료는 아니다.'),
     ('closed-loop', '더미가 응답을 기다리므로 목표 요청 빈도가 곧 실제로 일정하게 투입된 요청률은 아니다. 서버가 느리면 클라이언트의 다음 요청도 늦어질 수 있다.')],
    '동일한 실행 파일과 96명 더미를 사용해 다섯 조건을 각각 세 번 반복했습니다. 준비 3초 뒤 12초 구간을 측정했고 유닛·HP·스킬 등 시험 데이터를 고정했습니다. 연결당 Ping과 전투 요청의 목표 빈도는 있지만 응답을 기다리는 closed-loop이므로 무한히 입력을 밀어 넣는 최대 처리량 시험과 다릅니다. 뒤의 표는 실행별 지표 세 개의 중앙값입니다.',
    [('재현을 위해 남긴 것', '실행 파일 해시·INI/CSV 사본·각 run.json·원본 요청 표본 CSV·프로세스 자원 표본을 남겼다. 비교가 이상하면 집계 표만 보지 않고 해당 실행의 실제 요청 수·지연·누락과 서버 지표를 되짚는다.'),
     ('해석 범위', '동일 PC 루프백에서는 인터넷 손실·사용자 PC 차이·다중 호스트 병목이 빠져 있다. 낮은 부하에서 특정 구간의 비용과 응답 지연을 비교한 결과이며 서비스 수용량, 공정성, 지연 보정의 증거가 아니다.')],
    [('왜 세 번의 중앙값인가요?', '한 번의 우연한 값에만 의존하지 않기 위한 요약이다. 표본 세 개가 충분한 통계 검증을 뜻하지는 않아서 최소~최대 범위도 함께 제시했다.'),
     ('동일 부하면 정확히 같은 요청 개수인가요?', '동일한 설정·시나리오·인원을 뜻한다. 응답 대기형이므로 지연에 따라 실제 완료 요청 수는 달라질 수 있어 원본 표본과 완료량도 확인해야 한다.')],
    '목표 Ping 100회/초·전투 20회/초를 실제 달성 처리량이나 모든 실행의 동일 입력 수로 단정하지 않는다.',
    [('docs/results/2026-10-19/iocp/matrix/plan.json', None), ('docs/results/2026-10-19/iocp/summary.json', None), ('DummyClient/src/LoadClient.cpp', 'RunLoadClient(')])

add(32,
    '응답 왕복 시간과 서버 내부 Snapshot 구간을 별도 그래프로 놓아 하나의 지표 향상을 전체 성능 향상으로 오해하지 않게 한다. 수염은 세 번 반복의 범위를 보이는 장치다.',
    [('왼쪽 전투 RTT p95', '클라이언트가 전투 요청을 보내고 응답받은 시간의 높은 지연 구간이다. 실행별 p95를 구한 뒤 세 값의 중앙값을 사용한다.'),
     ('오른쪽 Snapshot 지표', '측정 구간 안의 1초 로그별 p95 중 최대값을 실행마다 구하고 그 세 값의 중앙값을 표시했다. 전체 Snapshot 개별 표본의 p95와 다르다.'),
     ('C → E의 차이', 'Snapshot 3.895→1.867ms는 약 52.1% 감소지만 전투 RTT 16.413→16.520ms는 비슷하다. 개선된 구간과 최종 응답 지표가 다르다.')],
    '왼쪽은 클라이언트 전투 응답 지연이고 오른쪽은 서버 Snapshot 구간 지표입니다. C에서 E로 전투 계산 쓰레드를 늘렸을 때 Snapshot 값은 약 52.1% 줄었지만 전투 RTT는 거의 같았습니다. 따라서 전체 서버가 두 배 빨라졌다고 말하지 않습니다. 오른쪽 값도 전체 표본 p95가 아니라 1초 로그별 p95 중 최대값의 반복 중앙값입니다.',
    [('p95를 말하는 방법', '평균과 달리 표본의 약 95%가 그 값 이하인 분위수를 말한다. 정확한 계산 방식은 집계 스크립트를 기준으로 한다. 세 실행의 p95를 다시 중앙값 낸 값은 세 실행 표본을 모두 합친 p95와 같다고 가정하면 안 된다.'),
     ('원인 설명의 절제', 'A→B의 전투 RTT 감소는 이 실행에서 네트워크 경로를 바꾼 결과와 일치한다. OS 스케줄링·루프 대기 등의 영향을 포함한 측정이며 IOCP가 모든 게임에 같은 배수 개선을 준다고 일반화할 수 없다. C→E도 Snapshot 일부 병렬 구간의 이득이다.')],
    [('전투 쓰레드 4개인데 RTT가 줄지 않은 이유는?', '측정한 요청 응답 경로에 입력 큐·메인 순서·동기화 등 다른 비용이 있고 병렬화되지 않은 구간도 있기 때문이다. 현재 표만으로 모든 원인의 비중을 확정할 수 없다.'),
     ('수염이 짧으면 안정적인 라이브 서버인가요?', '세 번의 짧은 실행에서 관찰된 범위가 좁다는 뜻이다. 장시간·다양한 네트워크·최대 부하의 안정성과는 별도 검증이 필요하다.')],
    '오른쪽 제목의 “구간 p95 최대”를 생략하지 않는다. 원본 수치의 집계 순서를 바꿔 더 유리한 숫자로 설명하지 않는다.',
    [('docs/results/2026-10-19/iocp/summary.json', None)])

add(33,
    '좋아진 신규 할당 수뿐 아니라 응답 지연·CPU·메모리를 같은 표에 두었다. 도입한 기술의 비용까지 공개해 실제로 무엇을 얻고 무엇이 남았는지 설명하는 장이다.',
    [('B → C 신규 생성 / 재사용', '풀 OFF의 79,096/0에서 풀 ON의 205/78,822로 바뀐다. I/O 객체 신규 생성 횟수가 줄고 반환된 객체를 재사용했다는 근거다.'),
     ('CPU와 메모리', 'CPU는 1코어=100% 기준의 구간 평균, 메모리는 World Working Set 표본 최대다. 16개 논리 CPU 전체의 작업 관리자 백분율과 같은 정의가 아니다.'),
     ('서로 다른 집계 단위', 'p95는 요청 지연, 메모리는 표본 최대, I/O 수는 실행 누계다. 열마다 정의가 다르므로 모든 수치를 같은 시점의 순간값으로 읽지 않는다.')],
    '풀을 켜면서 I/O 객체 신규 생성 중앙값은 크게 줄었습니다. 하지만 Ping과 전투 RTT는 뚜렷하게 개선됐다고 보기 어렵고, 재사용 블록을 보관하는 메모리는 늘었습니다. 전투 쓰레드를 늘린 조건도 CPU와 메모리 비용이 함께 있습니다. 그래서 할당 최적화가 전체 지연 개선과 같은 말은 아니라는 점을 이 표로 보여줍니다.',
    [('CPU 수치를 읽는 예', '표의 10.685%는 이 자료의 1코어=100% 기준 평균이다. 시스템 전체가 10.685%였다고 바로 바꿔 말하지 않는다. 비교 조건에서 같은 집계 기준을 사용했는지 확인한다.'),
     ('새로운 개선률을 만들지 않기', '79,096→205로 신규 생성 수가 줄었다고 모든 힙 할당이나 CPU 시간이 같은 비율로 줄었다고 계산하지 않는다. 메모리 풀은 I/O 작업 객체에만 적용했고 문자열·Protobuf 등 다른 할당은 남아 있다.')],
    [('그럼 풀이 쓸모없는 건가요?', '이 시험에서는 I/O 객체 재사용이라는 목적은 확인했지만 RTT 이득은 뚜렷하지 않았다. 다른 부하에서의 효과는 별도 측정해야 한다. 이득과 비용을 분리해 설명한다.'),
     ('메모리가 왜 늘었나요?', '반환 객체를 보관하는 풀과 추가 쓰레드·작업 상태 등 비용이 있다. 표는 그 결과를 보여주지만 각 원인의 메모리 기여량까지 분해 측정한 것은 아니다.')],
    '표는 World 프로세스 측정값이며 네 서버·더미·Redis·MSSQL의 총 시스템 비용 표가 아니다.',
    [('docs/results/2026-10-19/iocp/summary.json', None), ('MultiThreadServer/MultiThreadServer/src/IoBufferPool.cpp', 'string CIoBufferPool::Metrics(')])

add(34,
    '96명 설정 비교와 별도로 실제 다수 유닛의 진입·전투·사망·재입장을 시연했다는 점을 큰 세 숫자로 보여준다. 아래에는 성공 지표와 게임 거부, 종료 사유를 함께 적어 범위를 제한한다.',
    [('1500과 2668/2138', '최대 동시 World 1,500명, 시연 중 사망 2,668회와 사망 후 재입장 2,138회다. 계정 수와 누적 사건 수의 단위가 다르다.'),
     ('39.143ms와 생략 틱 0', '관찰한 개별 Tick 최대와 생략 틱 수다. 20Hz 목표 50ms와 비교할 수 있지만 모든 구간·모든 환경의 보장값은 아니다.'),
     ('세 저장소 대조와 종료', 'Redis·XML·MSSQL의 1,500명 최종 점수를 대조했고 네 서버의 잔여 I/O·사용 블록을 확인했다. 파일의 정상 종료와 경기 승패 종료를 구분한다.')],
    '별도 시연에서는 A·B·C에 각 500명, 최대 World 1,500명을 넣고 준비 후 240초 동안 전투와 사망 후 재입장을 진행했습니다. 연결·응답 오류는 0이었지만 게임 규칙상 거부는 따로 집계했습니다. 최종 점수는 세 저장 경로에서 대조했습니다. 시간 제한으로 정상 종료했기 때문에 winner=0이며 승자가 나온 경기라고 설명하지 않습니다.',
    [('현재 기본값과 다른 조건', '시연은 Network 4·DB 6·Battle 4·풀 8192, 건물 HP 750,000, 전투 20Hz·Replay 5Hz의 시험 사본이다. 현재 Server.ini 기본 Network/DB 2/2나 기본 건물 데이터로 얻은 결과라고 바꾸지 않는다.'),
     ('오류 0의 한계', 'Errors=0은 더미가 집계한 연결·응답 오류이고 Rejected=162,752는 게임 판정 거부다. 두 값을 숨기거나 합쳐서 전투 요청이 전부 성공했다고 말하지 않는다. 단회·동일 PC 시연이므로 인터넷 1,500명 장시간 수용량을 입증하지 않는다.')],
    [('사망 수보다 재입장이 적은 이유는?', '재입장에는 100초 대기가 있고 종료 직전 사망자는 시연 안에 재진입하지 못할 수 있다. 두 수는 다른 사건 집계여서 반드시 같아야 하는 값은 아니다.'),
     ('Replay complete=1인데 winner=0인 이유는?', '파일이 정상 Footer까지 저장됐다는 뜻과 경기가 승패로 종료됐다는 뜻이 다르다. 이 기록은 server_shutdown이며 SQL 경기 complete=0이다.')],
    '39.143ms는 전체 표본 평균이나 p95가 아니라 관찰된 개별 Tick 최대다. 1,500명은 시험 범위이지 상용 수용량 인증이 아니다.',
    [('docs/results/2026-10-19/iocp/stress-validation.json', None), ('docs/results/2026-10-19/iocp/summary.json', None)])

add(35,
    '마지막 요약을 추상적인 장점 목록 대신 코드 탐색표로 만들었다. 발표 뒤 특정 구현을 더 보고 싶다는 질문이 오면 바로 해당 함수로 돌아갈 수 있는 색인 역할이다.',
    [('접속 → 프레임 → 게임', 'CIocpServer와 PacketDispatch, CGameLogic으로 이어지는 핵심 통신 경로를 실제 파일·함수명으로 연결한다.'),
     ('전투 / 저장 / 기록', '계산 분배, 외부 저장 결과 회수, 기록 복원이라는 별도 관심사를 각 함수 묶음에 대응시킨다.'),
     ('확인된 범위와 한계', '실제 구현과 로그에 근거한다는 점, 이전 성능 측정 날짜와 이후 가독성 변경을 구분한다는 점을 마지막에 남긴다.')],
    '설명드린 구조를 실제 코드에서 확인할 수 있도록 함수별 색인을 정리했습니다. 입력 경로는 Run과 HandleClientPackets에서 Submit으로 이어지고, 메인이 HandlePacket과 Tick을 실행합니다. 계산·DB·Redis·기록은 각각 별도 경계를 가집니다. 측정한 개선과 아직 구현하지 않은 부분을 구분했고, 원하시는 지점은 이 표를 기준으로 소스를 바로 보여드리겠습니다.',
    [('실제로 파일을 여는 순서', '입력 질문은 IocpServer.cpp → PacketDispatch.cpp → GameLogic.cpp, 병렬 질문은 GameBattle.cpp → BattleWorkers.cpp, 기록 질문은 GameReplay.cpp → Replay.cpp → ReplayWindow.cpp로 이동한다. 정의와 호출부 둘 다 확인한다.'),
     ('AI 활용을 설명하는 태도', 'AI 보조 구현·문서화 사용 사실을 숨기지 않되 생성된 구조를 직접 이해하고 선택 이유·검증·한계를 설명한다. 파일명·수치·함수를 외워 말하는 것보다 입력과 수명·쓰레드 경계를 직접 추적할 수 있는지가 중요하다.')],
    [('어느 함수부터 보면 되나요?', '관심사에 따라 다르지만 전체 흐름은 RunTcpServer → IOCP 수신 → Submit/Update → HandleMove/Tick → SendPacket/PostSend 순서가 좋다.'),
     ('지금 추가할 우선순위는?', '목표 부하에서 프로파일링·대기 큐 지연·장시간 자원 추이를 확인하고 실제 병목을 좁히는 것이 우선이다. TLS·World 복구·맵별 실행 등은 현재 미구현 범위를 먼저 구분한다.')],
    '이 해설은 현재 소스와 과거 검증을 읽어 정리한 자료다. 이 PDF를 만든 것 자체가 새 부하 시험 수행을 뜻하지 않는다.',
    [('README.md', None), ('docs/CodeConventions.md', None), ('docs/results/2026-10-21/mutex-roles/validation.md', None)])

add(36,
    '기능 설명 뒤에 명명과 함수 분리를 둔 이유는 읽기 쉬운 구조가 실제로 어디에 반영됐는지 보여주기 위해서다. 스타일의 통일과 서버의 안전성·성능 검증은 별개의 책임으로 다룬다.',
    [('이름의 접두사', '클래스 C, 구조체 st, 클래스 멤버 m_, 전역 g_를 사용한다. 일반 포인터 p_, shared_ptr sp_, unique_ptr up_를 구분하며 weak_ptr wp_는 규칙만 있고 현재 사용처는 없다.'),
     ('요청·완료 함수 분리', 'HandlePacket이 서버 역할별 처리로 갈리고 HandleMove가 목적지 설정을 담당한다. Run은 IOCP 완료를 분배하고 HandleSessionCompletion이 기존 연결을 처리한다.'),
     ('역할이 보이는 잠금 이름', 'sessionMutex·m_commandsMutex·m_battleMutex처럼 보호 대상이 드러나게 한다. 이름을 바꿀 때 선언·사용·wait·문서를 함께 맞춘다.')],
    '코드를 읽는 사람이 상태의 소유자와 함수의 책임을 이름으로 찾을 수 있도록 정리했습니다. 포인터 종류와 멤버를 구분하고, 요청 처리와 I/O 등록·완료 처리를 별도 함수로 두었습니다. 잠금도 무엇을 보호하는지 이름에 표시했습니다. 이 정리는 가독성 변경이고 게임 동작이나 과거 측정 결과를 새 성과로 바꾸지는 않았습니다.',
    [('컨벤션과 실제 소유권', 'sp_라고 해서 객체 내부 동시 수정이 안전한 것은 아니고 p_라고 해서 무조건 비소유 포인터인 것도 아니다. I/O 객체는 풀과 완료 규칙으로 관리한다. 접두사는 읽는 단서이고 실제 타입·수명 관리 코드로 확인한다.'),
     ('변경 검증과 자료 동기화', '현재 역할별 mutex 정리는 소스·헤더 18개에서 이름 외 코드 토큰·리터럴 동일성을 비교하고 Debug/Release 및 기능·병렬 회귀를 확인했다. 모든 이름 변경마다 새로운 부하 개선률을 주장하지 않고 문서 코드 발췌도 같은 이름으로 맞춘다.')],
    [('채널과 세션의 잠금은 왜 따로 있나요?', 'sendMutex는 메인과 네트워크 사이 송신 우편함을, sessionMutex는 네트워크 완료 처리의 세션 상태를 보호한다. 다른 공유 데이터이므로 이름과 잠금 범위를 구분한다.'),
     ('스마트 포인터를 const 참조로 받으면 접두사는?', '포인터 객체의 종류가 shared_ptr이면 sp_다. 일반 stPlayer&는 포인터가 아니므로 player를 유지한다. 이름을 맞추려고 소유권이나 타입을 바꾸지는 않는다.')],
    '테마·지원 시안 같은 내부 관리 표기는 제출 이름에 넣지 않는다. 이 문서도 이름은 민수홍으로 표기한다.',
    [('docs/CodeConventions.md', None), ('MultiThreadServer/MultiThreadServer/src/IocpSession.h', 'struct stIocpSession'), ('docs/results/2026-10-21/mutex-roles/rename-audit.json', None)],
    ('MultiThreadServer/MultiThreadServer/src/IocpSession.h', 'struct stIocpSession', 'mutex sessionMutex;', 6))


